    /// 总费用；无解时为空 / Total cost, absent without a solution.
    #[wasm_bindgen(js_name = totalCost)]
    pub fn total_cost(&self) -> Option<f64> { self.value.solution.as_ref().map(|solution| solution.total_cost.value) }
    /// 弧结果数量 / Number of arc results.
    #[wasm_bindgen(js_name = arcCount)]
    pub fn arc_count(&self) -> u32 {
        self.value.solution.as_ref().map(|solution| u32::try_from(solution.arcs.len()).unwrap_or(u32::MAX)).unwrap_or(0)
    }
    /// 第 `index` 条弧的 `[id, 投入, 产出, 产率损耗, 费用]` / `[id, input, output, yield loss, cost]` of arc `index`.
    pub fn arc(&self, index: u32) -> Result<Vec<JsValue>, JsValue> {
        let solution = self.solution()?;
        let arc = solution.arcs.get(usize::try_from(index).map_err(|_| error("arc index overflow"))?)
            .ok_or_else(|| error("arc index out of range"))?;
        Ok(vec![JsValue::from_str(&arc.id), JsValue::from_f64(arc.input.value), JsValue::from_f64(arc.output.value),
            JsValue::from_f64(arc.loss_or_gain.value), JsValue::from_f64(arc.cost.value)])
    }
    /// 节点结果数量 / Number of node results.
    #[wasm_bindgen(js_name = nodeCount)]
    pub fn node_count(&self) -> u32 {
        self.value.solution.as_ref().map(|solution| u32::try_from(solution.nodes.len()).unwrap_or(u32::MAX)).unwrap_or(0)
    }
