    fn mapping(&self, position: u32)
        -> Result<&ospf_rust_bridge::PredicateFieldProbeReport, JsValue>
    {
        self.value.mappings.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .ok_or_else(|| error("predicate field mapping index out of range"))
    }
