    /// 域证明条数 / The number of proof checks.
    #[wasm_bindgen(js_name = proofCount)]
    pub fn proof_count(&self) -> u32 {
        u32::try_from(self.value.proofs.len()).unwrap_or(u32::MAX)
    }
