/// 弹性模型结论的独立 reader（续挖：`model/intermediate/linear_triad_model` + `elastic`）。
/// Independent reader for the elastic-model verdict (continuation).
#[wasm_bindgen]
pub struct ElasticModelReport { value: ospf_rust_bridge::ElasticModelReport }

#[wasm_bindgen]
impl ElasticModelReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<ElasticModelReport, JsValue> {
        if json.len() > 8 * 1024 * 1024 { return Err(error("elastic model report exceeds 8 MiB")); }
        let value: ospf_rust_bridge::ElasticModelReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：四条变换的顺序固定；弹性化的变量数 = 基模型变量数 + 约束数 × 每条约束的松弛数；
        // 松弛数只能是 0 或 1；每条松弛变量都是 `[0, +∞)` 连续且行系数为 -1；
        // 负 / 零罚项都不拒（所以报告不能声称拒了）；可行性模型的目标必须全零。
        // Read-side re-checks: the four transforms are in a fixed order; elastic variables equal base variables plus
        // constraints times slacks-per-constraint; that ratio is 0 or 1; every slack is `[0, +∞)`, continuous with row
        // coefficient -1; neither a negative nor a zero penalty may claim a refusal; and feasibility must zero the objective.
        if value.transforms.len() != 4 {
            return Err(error("elastic model report carries the wrong number of transforms"));
        }
        const ORDER: [&str; 4] = ["base", "elastic", "feasibility", "linearRelaxed"];
        for (row, expected) in value.transforms.iter().zip(ORDER) {
            if row.transform != expected {
                return Err(error("elastic model report carries its transforms out of order"));
            }
            if row.objective_length != row.variables {
                return Err(error("elastic model report objective length disagrees with its variables"));
            }
        }
        if value.slacks_per_constraint > 1 {
            return Err(error("elastic model report adds more than one slack per constraint"));
        }
        let base = &value.transforms[0];
        let elastic = &value.transforms[1];
        let expected = base.variables
            .saturating_add(base.constraints.saturating_mul(value.slacks_per_constraint));
        if elastic.variables != expected {
            return Err(error("elastic model report variable count disagrees with its slacks"));
        }
        if elastic.constraints != base.constraints {
            return Err(error("elastic model report changed the constraint count"));
        }
        if value.slacks.len() != usize::try_from(elastic.variables - base.variables)
            .map_err(|_| error("index overflow"))?
        {
            return Err(error("elastic model report slack list disagrees with the variable delta"));
        }
        for slack in &value.slacks {
            if slack.lower != 0.0 || !slack.upper_is_infinite || slack.kind != "continuous" {
                return Err(error("elastic model report carries a slack that is not a free non-negative"));
            }
            if slack.row_coefficient != Some(-1.0) {
                return Err(error("elastic model report carries a slack row coefficient that is not -1"));
            }
            if slack.name.trim().is_empty() {
                return Err(error("elastic model report carries a nameless slack"));
            }
        }
        if value.negative_penalty_refused || value.zero_penalty_refused {
            return Err(error("elastic model report claims the builder validates the penalty"));
        }
        if !value.transforms[2].objective_is_zero {
            return Err(error("elastic model report leaves a non-zero feasibility objective"));
        }
        for row in &value.transforms {
            if row.kinds.len() != usize::try_from(row.variables).map_err(|_| error("index overflow"))? {
                return Err(error("elastic model report kind list disagrees with its variables"));
            }
            if row.category != "min" && row.category != "max" {
                return Err(error("elastic model report carries an unknown objective direction"));
            }
        }
        // 弛缓映射里每一项的两侧都必须是已知类型名。 / Every relaxation pair names a known kind on both sides.
        const KINDS: [&str; 8] = ["continuous", "binary", "integer", "percentage", "ternary",
            "balancedTernary", "uinteger", "ucontinuous"];
        for pair in &value.relaxation_map {
            if !KINDS.contains(&pair.before.as_str()) || !KINDS.contains(&pair.after.as_str()) {
                return Err(error("elastic model report carries an unknown variable kind"));
            }
        }
        Ok(ElasticModelReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 变换条数 / The number of transforms.
    #[wasm_bindgen(js_name = transformCount)]
    pub fn transform_count(&self) -> u32 {
        u32::try_from(self.value.transforms.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个变换的名字 / The name of transform `position`.
    #[wasm_bindgen(js_name = transformName)]
    pub fn transform_name(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.transform(position)?.transform.clone())
    }
    /// 第 `position` 个变换后的变量数 / The variable count after transform `position`.
    #[wasm_bindgen(js_name = transformVariables)]
    pub fn transform_variables(&self, position: u32) -> Result<u32, JsValue> {
        Ok(self.transform(position)?.variables)
    }
    /// 第 `position` 个变换后的约束数 / The constraint count after transform `position`.
    #[wasm_bindgen(js_name = transformConstraints)]
    pub fn transform_constraints(&self, position: u32) -> Result<u32, JsValue> {
        Ok(self.transform(position)?.constraints)
    }
    /// 第 `position` 个变换后的目标系数个数 / The objective length after transform `position`.
    #[wasm_bindgen(js_name = transformObjectiveLength)]
    pub fn transform_objective_length(&self, position: u32) -> Result<u32, JsValue> {
        Ok(self.transform(position)?.objective_length)
    }
    /// 第 `position` 个变换后的目标方向 / The objective direction after transform `position`.
    #[wasm_bindgen(js_name = transformCategory)]
    pub fn transform_category(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.transform(position)?.category.clone())
    }
    /// 第 `position` 个变换后的目标是否全零 / Whether the objective is all zero after transform `position`.
    #[wasm_bindgen(js_name = transformObjectiveIsZero)]
    pub fn transform_objective_is_zero(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.transform(position)?.objective_is_zero)
    }
    /// 第 `position` 个变换后的变量类型序列 / The variable kinds after transform `position`.
    #[wasm_bindgen(js_name = transformKinds)]
    pub fn transform_kinds(&self, position: u32) -> Result<Vec<String>, JsValue> {
        Ok(self.transform(position)?.kinds.clone())
    }
    /// 松弛变量条数 / The number of slacks.
    #[wasm_bindgen(js_name = slackCount)]
    pub fn slack_count(&self) -> u32 {
        u32::try_from(self.value.slacks.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个松弛变量的列索引 / The column index of slack `position`.
    #[wasm_bindgen(js_name = slackIndex)]
    pub fn slack_index(&self, position: u32) -> Result<u32, JsValue> {
        Ok(self.slack(position)?.index)
    }
    /// 第 `position` 个松弛变量的名字 / The name of slack `position`.
    #[wasm_bindgen(js_name = slackName)]
    pub fn slack_name(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.slack(position)?.name.clone())
    }
    /// 第 `position` 个松弛变量的下界 / The lower bound of slack `position`.
    #[wasm_bindgen(js_name = slackLower)]
    pub fn slack_lower(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.slack(position)?.lower)
    }
    /// 第 `position` 个松弛变量的上界是否为正无穷 / Whether slack `position` is unbounded above.
    #[wasm_bindgen(js_name = slackUpperIsInfinite)]
    pub fn slack_upper_is_infinite(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.slack(position)?.upper_is_infinite)
    }
    /// 第 `position` 个松弛变量的行系数 / The row coefficient of slack `position`.
    #[wasm_bindgen(js_name = slackRowCoefficient)]
    pub fn slack_row_coefficient(&self, position: u32) -> Result<Option<f64>, JsValue> {
        Ok(self.slack(position)?.row_coefficient)
    }
    /// 第 `position` 个松弛变量的目标系数 / The objective coefficient of slack `position`.
    #[wasm_bindgen(js_name = slackObjectiveCoefficient)]
    pub fn slack_objective_coefficient(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.slack(position)?.objective_coefficient)
    }
    /// 每条约束新增的松弛变量数 / The slacks added per constraint.
    #[wasm_bindgen(js_name = slacksPerConstraint)]
    pub fn slacks_per_constraint(&self) -> u32 { self.value.slacks_per_constraint }
    /// 目标方向是否被强制成 `min` / Whether the direction was forced to `min`.
    #[wasm_bindgen(js_name = categoryForcedToMinimum)]
    pub fn category_forced_to_minimum(&self) -> bool { self.value.category_forced_to_minimum }
    /// 负罚项是否被拒 / Whether a negative penalty was refused.
    #[wasm_bindgen(js_name = negativePenaltyRefused)]
    pub fn negative_penalty_refused(&self) -> bool { self.value.negative_penalty_refused }
    /// 零罚项是否被拒 / Whether a zero penalty was refused.
    #[wasm_bindgen(js_name = zeroPenaltyRefused)]
    pub fn zero_penalty_refused(&self) -> bool { self.value.zero_penalty_refused }
    /// 松弛映射条数 / The number of relaxation pairs.
    #[wasm_bindgen(js_name = relaxationCount)]
    pub fn relaxation_count(&self) -> u32 {
        u32::try_from(self.value.relaxation_map.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 对松弛映射的来源类型 / The source kind of relaxation pair `position`.
    #[wasm_bindgen(js_name = relaxationBefore)]
    pub fn relaxation_before(&self, position: u32) -> Result<String, JsValue> {
        self.value.relaxation_map.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .map(|pair| pair.before.clone())
            .ok_or_else(|| error("elastic model relaxation index out of range"))
    }
    /// 第 `position` 对松弛映射的目标类型 / The target kind of relaxation pair `position`.
    #[wasm_bindgen(js_name = relaxationAfter)]
    pub fn relaxation_after(&self, position: u32) -> Result<String, JsValue> {
        self.value.relaxation_map.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .map(|pair| pair.after.clone())
            .ok_or_else(|| error("elastic model relaxation index out of range"))
    }
}

