    /// 孙片段剩余 / The grandchild's remainder.
    #[wasm_bindgen(js_name = grandchildRemaining)]
    pub fn grandchild_remaining(&self) -> f64 { self.value.grandchild.remaining as f64 }
    /// 孙片段是否被拒过 / Whether the grandchild was ever denied.
    #[wasm_bindgen(js_name = grandchildDenied)]
    pub fn grandchild_denied(&self) -> bool { self.value.grandchild.denied }
    /// 孙片段获批次数 / The grandchild's granted claims.
    #[wasm_bindgen(js_name = grandchildGranted)]
    pub fn grandchild_granted(&self) -> u32 { self.value.grandchild.granted }
    /// 随机流起始状态 / The random stream's starting state.
    #[wasm_bindgen(js_name = randomStateBefore)]
    pub fn random_state_before(&self) -> f64 { self.value.random.state_before as f64 }
    /// 抽取到的单位值 / The drawn unit values.
    #[wasm_bindgen(js_name = randomDraws)]
    pub fn random_draws(&self) -> Vec<f64> { self.value.random.draws.clone() }
    /// 抽取后的状态 / The state after drawing.
    #[wasm_bindgen(js_name = randomStateAfter)]
    pub fn random_state_after(&self) -> f64 { self.value.random.state_after as f64 }
    /// 快照状态 / The snapshot state.
    #[wasm_bindgen(js_name = randomSnapshotState)]
    pub fn random_snapshot_state(&self) -> f64 { self.value.random.snapshot_state as f64 }
    /// 从快照恢复后的抽取 / The draw after resuming.
    #[wasm_bindgen(js_name = randomResumedDraw)]
    pub fn random_resumed_draw(&self) -> f64 { self.value.random.resumed_draw }
    /// 恢复是否复现最后一次抽取 / Whether the resume reproduces the last draw.
    #[wasm_bindgen(js_name = randomResumeMatches)]
    pub fn random_resume_matches(&self) -> bool { self.value.random.resume_matches }
    /// 派生子流的起始状态 / The derived child stream's starting state.
    #[wasm_bindgen(js_name = randomSplitState)]
    pub fn random_split_state(&self) -> f64 { self.value.random.split_state as f64 }
    /// `split` 是否消费父流 / Whether `split` consumes the parent.
    #[wasm_bindgen(js_name = randomSplitMovesParent)]
    pub fn random_split_moves_parent(&self) -> bool { self.value.random.split_moves_parent }
    /// 同种子是否同序列 / Whether identical seeds agree.
    #[wasm_bindgen(js_name = randomIdenticalSeedsAgree)]
    pub fn random_identical_seeds_agree(&self) -> bool { self.value.random.identical_seeds_agree }
    /// 单位值是否都在 `[0,1)` / Whether every draw is in `[0, 1)`.
    #[wasm_bindgen(js_name = randomDrawsInUnitInterval)]
    pub fn random_draws_in_unit_interval(&self) -> bool {
        self.value.random.draws_in_unit_interval
    }
    /// 全局在额度用尽后停发 / Whether the global stops at its limit.
    #[wasm_bindgen(js_name = globalStopsAtLimit)]
    pub fn global_stops_at_limit(&self) -> bool { self.value.global_stops_at_limit }
    /// `steps` 不参与准入 / Whether `steps` fails to gate admission.
    #[wasm_bindgen(js_name = stepsDoNotGateAdmission)]
    pub fn steps_do_not_gate_admission(&self) -> bool { self.value.steps_do_not_gate_admission }
    /// 孙片段消耗计入子片段与全局 / Whether grandchild claims charge both.
    #[wasm_bindgen(js_name = childChargesParent)]
