/// 变量定义域结论的独立 reader（续挖：`variable/variable_type`）。
/// Independent reader for the variable-domain verdict (continuation).
#[wasm_bindgen]
pub struct VariableKindDomainReport { value: ospf_rust_bridge::VariableKindDomainReport }

#[wasm_bindgen]
impl VariableKindDomainReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<VariableKindDomainReport, JsValue> {
        if json.len() > 4 * 1024 * 1024 {
            return Err(error("variable kind domain report exceeds 4 MiB"));
        }
        let value: ospf_rust_bridge::VariableKindDomainReport =
            serde_json::from_str(json).map_err(error)?;
        // 读侧复核：必须恰是八种类型且枚举名与类型名一致；有界时 `min <= max`；
        // 每个 val 行的判定条数必须与探测表等长；`halfValid` / `largeValid` 必须与界相符
        // （界允许 0.5 就必须 `halfValid`，界不允许 1e9 就必须非 `largeValid`）。
        // Read-side re-checks: exactly eight kinds whose enum matches the type name; `min <= max` when bounded; each row's
        // verdict list matches the probe list; and `halfValid` / `largeValid` agree with the bounds.
        if value.kinds.len() != 8 {
            return Err(error("variable kind domain report carries the wrong number of kinds"));
        }
        if !value.kind_matches_type_name {
            return Err(error("variable kind domain report disagrees between kind and type name"));
        }
        let mut seen = std::collections::BTreeSet::new();
        for row in &value.kinds {
            if !seen.insert(row.kind.clone()) {
                return Err(error("variable kind domain report repeats a kind"));
            }
            if row.kind != row.type_name {
                return Err(error("variable kind domain report disagrees between kind and type name"));
            }
            if let (Some(min), Some(max)) = (row.min, row.max) {
                if min > max {
                    return Err(error("variable kind domain report carries inverted bounds"));
                }
            }
            if row.validity.len() != value.probes.len() {
                return Err(error("variable kind domain report carries a short verdict list"));
            }
            // `0.5` 的判定必须与界一致。 / The `0.5` verdict must follow the bounds.
            let half_allowed = row.min.is_none_or(|min| 0.5 >= min)
                && row.max.is_none_or(|max| 0.5 <= max);
            if row.half_valid != half_allowed {
                return Err(error("variable kind domain report mislabels whether a half is valid"));
            }
            let large_allowed = row.min.is_none_or(|min| 1.0e9 >= min)
                && row.max.is_none_or(|max| 1.0e9 <= max);
            if row.large_valid != large_allowed {
                return Err(error("variable kind domain report mislabels whether a large value is valid"));
            }
        }
        if !value.bounds_are_ordered || !value.unbounded_kinds_accept_large {
            return Err(error("variable kind domain report admits a broken bounds finding"));
        }
        Ok(VariableKindDomainReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 探测条数 / The number of probes.
    #[wasm_bindgen(js_name = probeCount)]
    pub fn probe_count(&self) -> u32 {
        u32::try_from(self.value.probes.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个探测值 / The probed value at `position`.
    #[wasm_bindgen(js_name = probe)]
    pub fn probe(&self, position: u32) -> Result<f64, JsValue> {
        self.value.probes.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .copied().ok_or_else(|| error("probe index out of range"))
    }
    /// 类型条数 / The number of kinds.
    #[wasm_bindgen(js_name = kindCount)]
    pub fn kind_count(&self) -> u32 {
        u32::try_from(self.value.kinds.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个类型的名字 / The kind name at `position`.
    #[wasm_bindgen(js_name = kindName)]
    pub fn kind_name(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.kind(position)?.kind.clone())
    }
    /// 第 `position` 个类型的下界 / The lower bound at `position`.
    #[wasm_bindgen(js_name = kindMin)]
    pub fn kind_min(&self, position: u32) -> Result<Option<f64>, JsValue> {
        Ok(self.kind(position)?.min)
    }
    /// 第 `position` 个类型的上界 / The upper bound at `position`.
    #[wasm_bindgen(js_name = kindMax)]
    pub fn kind_max(&self, position: u32) -> Result<Option<f64>, JsValue> {
        Ok(self.kind(position)?.max)
    }
    /// 第 `position` 个类型是否是整数类型 / Whether kind `position` is integral.
    #[wasm_bindgen(js_name = kindIsInteger)]
    pub fn kind_is_integer(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.kind(position)?.is_integer)
    }
    /// 第 `position` 个类型是否声明有符号 / Whether kind `position` declares itself signed.
    #[wasm_bindgen(js_name = kindIsSigned)]
    pub fn kind_is_signed(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.kind(position)?.is_signed)
    }
    /// 第 `position` 个类型是否接受 `0.5` / Whether kind `position` accepts `0.5`.
    #[wasm_bindgen(js_name = kindHalfValid)]
    pub fn kind_half_valid(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.kind(position)?.half_valid)
    }
    /// 第 `position` 个类型是否接受 `1e9` / Whether kind `position` accepts `1e9`.
    #[wasm_bindgen(js_name = kindLargeValid)]
    pub fn kind_large_valid(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.kind(position)?.large_valid)
    }
    /// 第 `position` 个类型第 `probe` 个取值的判定 / The verdict for probe `probe` on kind `position`.
    #[wasm_bindgen(js_name = kindValidAt)]
    pub fn kind_valid_at(&self, position: u32, probe: u32) -> Result<bool, JsValue> {
        let row = self.kind(position)?;
        row.validity.get(usize::try_from(probe).map_err(|_| error("index overflow"))?)
            .copied().ok_or_else(|| error("probe index out of range"))
    }
    /// 枚举与类型名一致 / Whether the enum matches the type name.
    #[wasm_bindgen(js_name = kindMatchesTypeName)]
    pub fn kind_matches_type_name(&self) -> bool { self.value.kind_matches_type_name }
    /// 有界时 `min <= max` / Whether bounded kinds are ordered.
    #[wasm_bindgen(js_name = boundsAreOrdered)]
    pub fn bounds_are_ordered(&self) -> bool { self.value.bounds_are_ordered }
    /// 整数性没被校验 / Whether integrality is unenforced.
    #[wasm_bindgen(js_name = integralityIsNotEnforced)]
    pub fn integrality_is_not_enforced(&self) -> bool { self.value.integrality_is_not_enforced }
    /// `Percentage` 的上界是 1 / Whether `Percentage` is bounded by 1.
    #[wasm_bindgen(js_name = percentageUpperIsOne)]
    pub fn percentage_upper_is_one(&self) -> bool { self.value.percentage_upper_is_one }
    /// 无界类型接受大值 / Whether unbounded kinds accept large values.
    #[wasm_bindgen(js_name = unboundedKindsAcceptLarge)]
    pub fn unbounded_kinds_accept_large(&self) -> bool { self.value.unbounded_kinds_accept_large }
    /// 有符号与下界是两套信息 / Whether signedness is independent of the lower bound.
    #[wasm_bindgen(js_name = signednessIsIndependent)]
    pub fn signedness_is_independent(&self) -> bool { self.value.signedness_is_independent }
}

impl VariableKindDomainReport {
    /// 取第 `position` 个类型 / Fetch kind `position`.
    fn kind(&self, position: u32) -> Result<&ospf_rust_bridge::VariableKindRow, JsValue> {
        self.value.kinds.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .ok_or_else(|| error("kind index out of range"))
    }
}

