/// 缓存键身份结论的独立 reader（续挖：`model/flatten` 的 `CacheKey`）。
/// Independent reader for the cache-key identity verdict (continuation).
#[wasm_bindgen]
pub struct FlattenIdentityReport { value: ospf_rust_bridge::FlattenIdentityReport }

#[wasm_bindgen]
impl FlattenIdentityReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<FlattenIdentityReport, JsValue> {
        if json.len() > 1024 * 1024 { return Err(error("flatten identity report exceeds 1 MiB")); }
        let value: ospf_rust_bridge::FlattenIdentityReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：三条"内容相同键不同"的事实必须互相一致——若键值真的两两不等，对应标志就必须为真，反之亦然。
        // Read-side re-checks: the three "equal content, distinct keys" facts must agree with the keys themselves.
        let distinct = value.first_key != value.clone_key
            && value.first_key != value.twin_key
            && value.clone_key != value.twin_key;
        if value.equal_content_gives_distinct_keys != distinct {
            return Err(error("flatten identity report mislabels whether equal content shares a key"));
        }
        if value.clone_gets_its_own_key != (value.first_key != value.clone_key) {
            return Err(error("flatten identity report mislabels the clone key"));
        }
        if !value.equal_content_gives_distinct_keys || !value.clone_gets_its_own_key
            || !value.from_raw_forges_collisions || !value.hashset_does_not_dedupe
            || !value.rebuilt_polynomial_gets_a_fresh_key
        {
            return Err(error("flatten identity report admits a broken address finding"));
        }
        if value.first_key == 0 || value.twin_key == 0 {
            return Err(error("flatten identity report carries a null key"));
        }
        if !value.coefficient.is_finite() {
            return Err(error("flatten identity report carries a non-finite coefficient"));
        }
        Ok(FlattenIdentityReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 本体键（地址，**二进制字符串**以免 f64 精度丢失） / The original key (an address, as a binary string).
    #[wasm_bindgen(js_name = firstKey)]
    pub fn first_key(&self) -> String { self.value.first_key.to_string() }
    /// 克隆体的键 / The clone's key.
    #[wasm_bindgen(js_name = cloneKey)]
    pub fn clone_key(&self) -> String { self.value.clone_key.to_string() }
    /// 独立构造者的键 / The twin's key.
    #[wasm_bindgen(js_name = twinKey)]
    pub fn twin_key(&self) -> String { self.value.twin_key.to_string() }
    /// 内容相同但键不同 / Whether equal content gives distinct keys.
    #[wasm_bindgen(js_name = equalContentGivesDistinctKeys)]
    pub fn equal_content_gives_distinct_keys(&self) -> bool {
        self.value.equal_content_gives_distinct_keys
    }
    /// `clone()` 换新键 / Whether `clone()` gets its own key.
    #[wasm_bindgen(js_name = cloneGetsItsOwnKey)]
    pub fn clone_gets_its_own_key(&self) -> bool { self.value.clone_gets_its_own_key }
    /// 内容不同键也不同 / Whether different content gives a different key.
    #[wasm_bindgen(js_name = differentContentGivesDistinctKeys)]
    pub fn different_content_gives_distinct_keys(&self) -> bool {
        self.value.different_content_gives_distinct_keys
    }
    /// `from_raw` 可伪造 / Whether `from_raw` forges collisions.
    #[wasm_bindgen(js_name = fromRawForgesCollisions)]
    pub fn from_raw_forges_collisions(&self) -> bool { self.value.from_raw_forges_collisions }
    /// 集合不按内容去重 / Whether a key set fails to dedupe by content.
    #[wasm_bindgen(js_name = hashsetDoesNotDedupe)]
    pub fn hashset_does_not_dedupe(&self) -> bool { self.value.hashset_does_not_dedupe }
    /// 重建换新键 / Whether a rebuild gets a fresh key.
    #[wasm_bindgen(js_name = rebuiltPolynomialGetsAFreshKey)]
    pub fn rebuilt_polynomial_gets_a_fresh_key(&self) -> bool {
        self.value.rebuilt_polynomial_gets_a_fresh_key
    }
    /// 单项式是线性项 / Whether the monomial is linear.
    #[wasm_bindgen(js_name = monomialIsLinear)]
    pub fn monomial_is_linear(&self) -> bool { self.value.monomial_is_linear }
    /// 系数回读 / The coefficient.
    #[wasm_bindgen(js_name = coefficient)]
    pub fn coefficient(&self) -> f64 { self.value.coefficient }
}

/// master cut 结论的独立 reader（续挖：`solver/logic_based_benders` 的 `MasterCut`）。
/// Independent reader for the master-cut verdict (continuation).
#[wasm_bindgen]
pub struct MasterCutReport { value: ospf_rust_bridge::MasterCutReport }

#[wasm_bindgen]
impl MasterCutReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<MasterCutReport, JsValue> {
        if json.len() > 1024 * 1024 { return Err(error("master cut report exceeds 1 MiB")); }
        let value: ospf_rust_bridge::MasterCutReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：规范化之后不得有零系数；项必须按变量 ID 严格升序（`BTreeMap` 的结果）；
        // `Verified` 必须带证明引用；九条规则属性必须为真。
        // Read-side re-checks: no zero coefficient survives normalization; terms are strictly ascending by variable ID
        // (what a `BTreeMap` yields); `Verified` carries a reference; and the nine rule properties hold.
        if value.normalized {
            for row in &value.terms {
                if row.coefficient == 0.0 || !row.coefficient.is_finite() {
                    return Err(error("master cut report kept a degenerate coefficient after normalize"));
                }
            }
            if value.proof_status == "Verified" && value.proof_reference.is_none() {
                return Err(error("master cut report claims verification without a reference"));
            }
        }
        for pair in value.terms.windows(2) {
            if pair[0].variable >= pair[1].variable {
                return Err(error("master cut report carries unordered or duplicate terms"));
            }
        }
        if value.term_count as usize != value.terms.len() {
            return Err(error("master cut report disagrees between its term count and its terms"));
        }
        if !value.new_merges_duplicates || !value.new_keeps_zeros || !value.normalize_drops_zeros
            || !value.normalize_refuses_blank_id || !value.normalize_refuses_non_finite_rhs
            || !value.verified_needs_reference || !value.blank_reference_is_dropped
            || !value.expression_key_ignores_identity || !value.normalize_is_idempotent
        {
            return Err(error("master cut report admits a broken invariant finding"));
        }
        if value.expression_key.is_empty() {
            return Err(error("master cut report carries an empty expression key"));
        }
        if !value.rhs.is_finite() {
            return Err(error("master cut report carries a non-finite rhs"));
        }
        Ok(MasterCutReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 是否规范化过 / Whether `normalize` ran.
    #[wasm_bindgen(js_name = normalized)]
    pub fn normalized(&self) -> bool { self.value.normalized }
    /// cut ID / The cut ID.
    #[wasm_bindgen(js_name = id)]
    pub fn id(&self) -> String { self.value.id.clone() }
    /// 方向 / The sense.
    #[wasm_bindgen(js_name = sense)]
    pub fn sense(&self) -> String { self.value.sense.clone() }
    /// 右端项 / The right-hand side.
    #[wasm_bindgen(js_name = rhs)]
    pub fn rhs(&self) -> f64 { self.value.rhs }
    /// 项数 / The number of terms.
    #[wasm_bindgen(js_name = termCount)]
    pub fn term_count(&self) -> f64 { self.value.term_count as f64 }
    /// 第 `position` 项的变量 ID / The variable ID at `position`.
    #[wasm_bindgen(js_name = termVariable)]
    pub fn term_variable(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.term(position)?.variable.clone())
    }
    /// 第 `position` 项的系数 / The coefficient at `position`.
    #[wasm_bindgen(js_name = termCoefficient)]
    pub fn term_coefficient(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.term(position)?.coefficient)
    }
    /// 证明状态 / The proof status.
    #[wasm_bindgen(js_name = proofStatus)]
    pub fn proof_status(&self) -> String { self.value.proof_status.clone() }
    /// 证明引用 / The proof reference.
    #[wasm_bindgen(js_name = proofReference)]
    pub fn proof_reference(&self) -> Option<String> { self.value.proof_reference.clone() }
    /// 有效性范围 / The validity scope.
    #[wasm_bindgen(js_name = validity)]
    pub fn validity(&self) -> String { self.value.validity.clone() }
    /// 编码类型 / The encoding kind.
    #[wasm_bindgen(js_name = encoding)]
    pub fn encoding(&self) -> String { self.value.encoding.clone() }
    /// 表达式身份 / The expression identity.
    #[wasm_bindgen(js_name = expressionKey)]
    pub fn expression_key(&self) -> String { self.value.expression_key.clone() }
    /// `new` 合并同变量 / Whether `new` merges duplicates.
    #[wasm_bindgen(js_name = newMergesDuplicates)]
    pub fn new_merges_duplicates(&self) -> bool { self.value.new_merges_duplicates }
    /// `new` 保留零系数 / Whether `new` keeps zeros.
    #[wasm_bindgen(js_name = newKeepsZeros)]
    pub fn new_keeps_zeros(&self) -> bool { self.value.new_keeps_zeros }
    /// `normalize` 丢零系数 / Whether `normalize` drops zeros.
    #[wasm_bindgen(js_name = normalizeDropsZeros)]
    pub fn normalize_drops_zeros(&self) -> bool { self.value.normalize_drops_zeros }
    /// `normalize` 拒空白 ID / Whether `normalize` refuses a blank ID.
    #[wasm_bindgen(js_name = normalizeRefusesBlankId)]
    pub fn normalize_refuses_blank_id(&self) -> bool { self.value.normalize_refuses_blank_id }
    /// `normalize` 拒非有限 `rhs` / Whether `normalize` refuses a non-finite `rhs`.
    #[wasm_bindgen(js_name = normalizeRefusesNonFiniteRhs)]
    pub fn normalize_refuses_non_finite_rhs(&self) -> bool {
        self.value.normalize_refuses_non_finite_rhs
    }
    /// `Verified` 必须带引用 / Whether `Verified` needs a reference.
    #[wasm_bindgen(js_name = verifiedNeedsReference)]
    pub fn verified_needs_reference(&self) -> bool { self.value.verified_needs_reference }
    /// 空白引用被丢掉 / Whether a blank reference is dropped.
    #[wasm_bindgen(js_name = blankReferenceIsDropped)]
    pub fn blank_reference_is_dropped(&self) -> bool { self.value.blank_reference_is_dropped }
    /// 表达式身份忽略出处 / Whether the expression key ignores provenance.
    #[wasm_bindgen(js_name = expressionKeyIgnoresIdentity)]
    pub fn expression_key_ignores_identity(&self) -> bool {
        self.value.expression_key_ignores_identity
    }
    /// `normalize` 幂等 / Whether `normalize` is idempotent.
    #[wasm_bindgen(js_name = normalizeIsIdempotent)]
    pub fn normalize_is_idempotent(&self) -> bool { self.value.normalize_is_idempotent }
}

