/// 布尔作用域折叠结论的独立 reader（续挖：`persistence/expression/boolean_expression_dsl`）。
/// Independent reader for the boolean-scope folding verdict (continuation).
#[wasm_bindgen]
pub struct BooleanFoldReport { value: ospf_rust_bridge::BooleanFoldReport }

#[wasm_bindgen]
impl BooleanFoldReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<BooleanFoldReport, JsValue> {
        if json.len() > 1024 * 1024 { return Err(error("boolean fold report exceeds 1 MiB")); }
        let value: ospf_rust_bridge::BooleanFoldReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：空作用域的两个形状必须恰好是 and→true / or→false；`and(0)` / `or(0)` 这类空组合不该出现；
        // 形状前缀必须与节点数自洽（单个节点 ⇒ 不是 and/or）。
        // Read-side re-checks: the two empty shapes are exactly and→true / or→false; no empty `and(0)` / `or(0)`
        // combination appears; and the shape prefix agrees with the node count (one node ⇒ neither and nor or).
        if value.empty_and_shape != "constant(true)" || value.empty_or_shape != "constant(false)" {
            return Err(error("boolean fold report carries the wrong empty-scope constants"));
        }
        for shape in [&value.shape, &value.empty_and_shape, &value.empty_or_shape] {
            if shape.contains("and(0)") || shape.contains("or(0)") {
                return Err(error("boolean fold report carries an empty combination"));
            }
            if shape.trim().is_empty() {
                return Err(error("boolean fold report carries a blank shape"));
            }
        }
        let is_combination = value.shape.starts_with("and(") || value.shape.starts_with("or(");
        if !is_combination && value.node_count != 1 {
            return Err(error("boolean fold report disagrees between a plain node and its node count"));
        }
        if is_combination && value.node_count < 3 {
            return Err(error("boolean fold report disagrees between a combination and its node count"));
        }
        if !value.single_element_loses_wrapper || !value.empty_scope_is_constant
            || !value.trailing_suffix_folds || !value.wrong_order_does_not_fold
            || !value.single_argument_unwraps || !value.interleaved_item_survives
        {
            return Err(error("boolean fold report admits a broken folding finding"));
        }
        Ok(BooleanFoldReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 合成结果的形状 / The built shape.
    #[wasm_bindgen(js_name = shape)]
    pub fn shape(&self) -> String { self.value.shape.clone() }
    /// 合成结果的节点数 / The built node count.
    #[wasm_bindgen(js_name = nodeCount)]
    pub fn node_count(&self) -> f64 { self.value.node_count as f64 }
    /// 空 `and` 的形状 / The empty `and` shape.
    #[wasm_bindgen(js_name = emptyAndShape)]
    pub fn empty_and_shape(&self) -> String { self.value.empty_and_shape.clone() }
    /// 空 `or` 的形状 / The empty `or` shape.
    #[wasm_bindgen(js_name = emptyOrShape)]
    pub fn empty_or_shape(&self) -> String { self.value.empty_or_shape.clone() }
    /// 单元素不带外壳 / Whether a single element loses its wrapper.
    #[wasm_bindgen(js_name = singleElementLosesWrapper)]
    pub fn single_element_loses_wrapper(&self) -> bool { self.value.single_element_loses_wrapper }
    /// 空作用域给常量 / Whether an empty scope yields a constant.
    #[wasm_bindgen(js_name = emptyScopeIsConstant)]
    pub fn empty_scope_is_constant(&self) -> bool { self.value.empty_scope_is_constant }
    /// 尾部后缀被折叠 / Whether a collected trailing suffix folds.
    #[wasm_bindgen(js_name = trailingSuffixFolds)]
    pub fn trailing_suffix_folds(&self) -> bool { self.value.trailing_suffix_folds }
    /// 顺序不同就不折叠 / Whether a different order does not fold.
    #[wasm_bindgen(js_name = wrongOrderDoesNotFold)]
    pub fn wrong_order_does_not_fold(&self) -> bool { self.value.wrong_order_does_not_fold }
    /// 单参数直接就是那一项 / Whether a single argument is the term itself.
    #[wasm_bindgen(js_name = singleArgumentUnwraps)]
    pub fn single_argument_unwraps(&self) -> bool { self.value.single_argument_unwraps }
    /// 折叠不是去重 / Whether folding is not a dedupe.
    #[wasm_bindgen(js_name = interleavedItemSurvives)]
    pub fn interleaved_item_survives(&self) -> bool { self.value.interleaved_item_survives }
}

