/// 有效性排序聚合结论的独立 reader（续挖：`analysis/pipeline` 的 `build_effectiveness_ranking`）。
/// Independent reader for the effectiveness-aggregation verdict (continuation).
#[wasm_bindgen]
pub struct EffectivenessAggregateReport { value: ospf_rust_bridge::EffectivenessAggregateReport }

#[wasm_bindgen]
impl EffectivenessAggregateReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<EffectivenessAggregateReport, JsValue> {
        if json.len() > 4 * 1024 * 1024 { return Err(error("effectiveness aggregate report exceeds 4 MiB")); }
        let value: ospf_rust_bridge::EffectivenessAggregateReport =
            serde_json::from_str(json).map_err(error)?;
        // 读侧复核：`order` 必须与 `rows` 的 ID 序列一致；已证明改善降序（`None` 最后）；
        // 有删除结论却无改善的行必须被标成"两份判据不一致"。
        // Read-side re-checks: `order` matches the row IDs; proven improvement is descending with `None` last; and a row
        // with a removal verdict but no gain must be marked as the two predicates disagreeing.
        if value.order.len() != value.rows.len() {
            return Err(error("effectiveness aggregate report disagrees on the row count"));
        }
        if value.order.iter().zip(value.rows.iter())
            .any(|(id, row)| id != &row.constraint_id)
        {
            return Err(error("effectiveness aggregate report disagrees on the ranking order"));
        }
        let gains: Vec<f64> = value.rows.iter()
            .map(|row| row.max_improvement.unwrap_or(f64::NEG_INFINITY)).collect();
        if gains.windows(2).any(|pair| pair[0] < pair[1]) {
            return Err(error("effectiveness aggregate report is not sorted by proven improvement"));
        }
        for row in &value.rows {
            if row.globally_effective != row.max_improvement.is_some_and(|value| value > 0.0) {
                return Err(error("effectiveness aggregate report mislabels a global verdict"));
            }
            if row.predicates_agree == (row.globally_effective != row.report_has_global_improvement)
            {
                return Err(error("effectiveness aggregate report mislabels predicate agreement"));
            }
            if row.max_improvement.is_some_and(|value| !value.is_finite())
                || row.first_effective_delta.is_some_and(|value| !value.is_finite() || value <= 0.0)
                || row.marginal_effect.is_some_and(|value| !value.is_finite())
            {
                return Err(error("effectiveness aggregate report carries a bad numeric value"));
            }
            if row.marginal_effect.is_some() && row.first_effective_delta.is_none() {
                return Err(error("effectiveness aggregate report has a marginal effect without a delta"));
            }
        }
        if value.rows.iter().filter(|row| row.constraint_id.trim().is_empty()).count() > 0 {
            return Err(error("effectiveness aggregate report carries a blank constraint"));
        }
        if !value.unproven_observations_are_ignored || !value.removal_improvement_is_not_a_gain
            || !value.the_two_predicates_can_disagree || !value.marginal_effect_needs_positive_delta
            || !value.first_delta_is_the_smallest || !value.none_improvement_sorts_last
            || !value.ties_fall_back_to_absolute_dual || !value.missing_candidate_is_unclassified
        {
            return Err(error("effectiveness aggregate report admits a broken aggregation finding"));
        }
        Ok(EffectivenessAggregateReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 行数 / The row count.
    #[wasm_bindgen(js_name = rowCount)]
    pub fn row_count(&self) -> u32 {
        u32::try_from(self.value.rows.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 行的约束 ID / The constraint of row `position`.
    #[wasm_bindgen(js_name = rowConstraintId)]
    pub fn row_constraint_id(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.row(position)?.constraint_id.clone())
    }
    /// 第 `position` 行的分层 / The tier of row `position`.
    #[wasm_bindgen(js_name = rowTier)]
    pub fn row_tier(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.row(position)?.tier.clone())
    }
    /// 第 `position` 行的最大改善 / The max improvement of row `position`.
    #[wasm_bindgen(js_name = rowMaxImprovement)]
    pub fn row_max_improvement(&self, position: u32) -> Result<Option<f64>, JsValue> {
        Ok(self.row(position)?.max_improvement)
    }
    /// 第 `position` 行的 first delta / The first delta of row `position`.
    #[wasm_bindgen(js_name = rowFirstEffectiveDelta)]
    pub fn row_first_effective_delta(&self, position: u32) -> Result<Option<f64>, JsValue> {
        Ok(self.row(position)?.first_effective_delta)
    }
    /// 第 `position` 行的边际效应 / The marginal effect of row `position`.
    #[wasm_bindgen(js_name = rowMarginalEffect)]
    pub fn row_marginal_effect(&self, position: u32) -> Result<Option<f64>, JsValue> {
        Ok(self.row(position)?.marginal_effect)
    }
    /// 第 `position` 行的删除结论 / The removal verdict of row `position`.
    #[wasm_bindgen(js_name = rowRemovalEffective)]
    pub fn row_removal_effective(&self, position: u32) -> Result<Option<bool>, JsValue> {
        Ok(self.row(position)?.removal_effective)
    }
    /// 第 `position` 行是否被排序判为全局有效 / Whether the ranking calls row `position` globally effective.
    #[wasm_bindgen(js_name = rowGloballyEffective)]
    pub fn row_globally_effective(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.row(position)?.globally_effective)
    }
    /// 第 `position` 行的报告侧改善判据 / The report-side predicate of row `position`.
    #[wasm_bindgen(js_name = rowReportHasGlobalImprovement)]
    pub fn row_report_has_global_improvement(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.row(position)?.report_has_global_improvement)
    }
    /// 第 `position` 行的两份判据是否一致 / Whether the two predicates agree on row `position`.
    #[wasm_bindgen(js_name = rowPredicatesAgree)]
    pub fn row_predicates_agree(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.row(position)?.predicates_agree)
    }
    /// 排序顺序里的第 `position` 个 ID / The ID at `position` in the ranking order.
    #[wasm_bindgen(js_name = orderAt)]
    pub fn order_at(&self, position: u32) -> Result<String, JsValue> {
        self.value.order.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("order index out of range"))
    }
    /// 未证明观察被排除 / Whether unproven observations are excluded.
    #[wasm_bindgen(js_name = unprovenObservationsAreIgnored)]
    pub fn unproven_observations_are_ignored(&self) -> bool {
        self.value.unproven_observations_are_ignored
    }
    /// 删除改善不算增益 / Whether a removal improvement is not a gain.
    #[wasm_bindgen(js_name = removalImprovementIsNotAGain)]
    pub fn removal_improvement_is_not_a_gain(&self) -> bool {
        self.value.removal_improvement_is_not_a_gain
    }
    /// 两份判据可以不一致 / Whether the two predicates can disagree.
    #[wasm_bindgen(js_name = theTwoPredicatesCanDisagree)]
    pub fn the_two_predicates_can_disagree(&self) -> bool {
        self.value.the_two_predicates_can_disagree
    }
    /// 边际效应需要正 delta / Whether the marginal effect needs a positive delta.
    #[wasm_bindgen(js_name = marginalEffectNeedsPositiveDelta)]
    pub fn marginal_effect_needs_positive_delta(&self) -> bool {
        self.value.marginal_effect_needs_positive_delta
    }
    /// first delta 取最小 / Whether the first delta is the smallest.
    #[wasm_bindgen(js_name = firstDeltaIsTheSmallest)]
    pub fn first_delta_is_the_smallest(&self) -> bool { self.value.first_delta_is_the_smallest }
    /// `None` 改善排最后 / Whether `None` improvement sorts last.
    #[wasm_bindgen(js_name = noneImprovementSortsLast)]
    pub fn none_improvement_sorts_last(&self) -> bool { self.value.none_improvement_sorts_last }
    /// 同改善时按 |dual| 降序 / Whether ties fall back to absolute dual.
    #[wasm_bindgen(js_name = tiesFallBackToAbsoluteDual)]
    pub fn ties_fall_back_to_absolute_dual(&self) -> bool {
        self.value.ties_fall_back_to_absolute_dual
    }
    /// 缺候选不是不重要 / Whether a missing candidate is not "unimportant".
    #[wasm_bindgen(js_name = missingCandidateIsUnclassified)]
    pub fn missing_candidate_is_unclassified(&self) -> bool {
        self.value.missing_candidate_is_unclassified
    }
}

