/// CP assumption 绑定结论的独立 reader（续挖：`solver/logic_based_benders`）。
/// Independent reader for the CP assumption-binding verdict (continuation).
#[wasm_bindgen]
pub struct AssumptionBindingReport { value: ospf_rust_bridge::AssumptionBindingReport }

#[wasm_bindgen]
impl AssumptionBindingReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<AssumptionBindingReport, JsValue> {
        if json.len() > 1024 * 1024 { return Err(error("assumption binding report exceeds 1 MiB")); }
        let value: ospf_rust_bridge::AssumptionBindingReport =
            serde_json::from_str(json).map_err(error)?;
        // 读侧复核：身份前缀必须落在五种之内；`sparse-domain` 之外的身份不得带值域条数；
        // 每条 assumption 都必须有映射（"恰好覆盖一次"的读侧体现）；冲突成员必须都在映射值里。
        // Read-side re-checks: every prefix is one of the five; only `sparse-domain` may carry a value count; every
        // assumption has a mapping (the read-side of "cover exactly once"); and every conflict member is a mapped value.
        if value.rows.iter().any(|row| !matches!(row.prefix.as_str(),
            "literal" | "equal" | "lower-bound" | "upper-bound" | "sparse-domain"))
        {
            return Err(error("assumption binding report carries an unknown identity prefix"));
        }
        if value.rows.iter().any(|row| row.stable_id.trim().is_empty()) {
            return Err(error("assumption binding report carries a blank identity"));
        }
        if value.rows.iter().any(|row| {
            (row.prefix == "sparse-domain" && row.value_count == 0)
                || (row.prefix != "sparse-domain" && row.value_count != 0)
        }) {
            return Err(error("assumption binding report mislabels the domain value count"));
        }
        if value.rows.iter().any(|row| !row.stable_id.starts_with(&format!("{}/", row.prefix))) {
            return Err(error("assumption binding report disagrees between a prefix and its identity"));
        }
        if value.mapping.len() != value.rows.len() {
            return Err(error("assumption binding report does not cover every assumption"));
        }
        let identities: std::collections::BTreeSet<&str> =
            value.rows.iter().map(|row| row.stable_id.as_str()).collect();
        if value.mapping.iter().any(|entry| !identities.contains(entry.assumption.as_str())) {
            return Err(error("assumption binding report maps an unknown assumption"));
        }
        if value.mapping.iter().any(|entry| entry.master_variable.trim().is_empty()) {
            return Err(error("assumption binding report carries a blank master variable"));
        }
        let masters: std::collections::BTreeSet<&str> = value.mapping.iter()
            .map(|entry| entry.master_variable.as_str()).collect();
        if value.conflict_members.iter().any(|member| !masters.contains(member.as_str())) {
            return Err(error("assumption binding report carries an unmapped conflict member"));
        }
        if value.conflict_members.is_empty() {
            return Err(error("assumption binding report carries an empty conflict subset"));
        }
        if value.proof_reference.trim().is_empty() {
            return Err(error("assumption binding report carries a blank proof reference"));
        }
        if !value.identity_is_length_prefixed || !value.sparse_domain_identity_ignores_values
            || !value.different_domains_collide || !value.different_numbers_do_not_collide
            || !value.polarity_is_part_of_the_identity || !value.domain_values_are_normalized
            || !value.separators_are_unambiguous || !value.mapping_must_cover_exactly_once
        {
            return Err(error("assumption binding report admits a broken identity finding"));
        }
        Ok(AssumptionBindingReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// assumption 条数 / The assumption count.
    #[wasm_bindgen(js_name = rowCount)]
    pub fn row_count(&self) -> u32 {
        u32::try_from(self.value.rows.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 条的稳定身份 / The identity at `position`.
    #[wasm_bindgen(js_name = rowStableId)]
    pub fn row_stable_id(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.row(position)?.stable_id.clone())
    }
    /// 第 `position` 条的身份前缀 / The prefix at `position`.
    #[wasm_bindgen(js_name = rowPrefix)]
    pub fn row_prefix(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.row(position)?.prefix.clone())
    }
    /// 第 `position` 条的值域条数 / The value count at `position`.
    #[wasm_bindgen(js_name = rowValueCount)]
    pub fn row_value_count(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.row(position)?.value_count as f64)
    }
    /// 映射条数 / The mapping count.
    #[wasm_bindgen(js_name = mappingCount)]
    pub fn mapping_count(&self) -> u32 {
        u32::try_from(self.value.mapping.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 条映射的 assumption 身份 / The assumption identity of mapping `position`.
    #[wasm_bindgen(js_name = mappingAssumption)]
    pub fn mapping_assumption(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.mapping(position)?.assumption.clone())
    }
    /// 第 `position` 条映射的 master 变量 / The master variable of mapping `position`.
    #[wasm_bindgen(js_name = mappingMasterVariable)]
    pub fn mapping_master_variable(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.mapping(position)?.master_variable.clone())
    }
    /// 冲突成员条数 / The conflict member count.
    #[wasm_bindgen(js_name = conflictMemberCount)]
    pub fn conflict_member_count(&self) -> u32 {
        u32::try_from(self.value.conflict_members.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个冲突成员 / The conflict member at `position`.
    #[wasm_bindgen(js_name = conflictMember)]
    pub fn conflict_member(&self, position: u32) -> Result<String, JsValue> {
        self.value.conflict_members
            .get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("conflict member index out of range"))
    }
    /// 证明引用 / The proof reference.
    #[wasm_bindgen(js_name = proofReference)]
    pub fn proof_reference(&self) -> String { self.value.proof_reference.clone() }
    /// 身份是长度前缀 / Whether identities are length-prefixed.
    #[wasm_bindgen(js_name = identityIsLengthPrefixed)]
    pub fn identity_is_length_prefixed(&self) -> bool { self.value.identity_is_length_prefixed }
    /// 值域不进身份 / Whether domain values stay out of the identity.
    #[wasm_bindgen(js_name = sparseDomainIdentityIgnoresValues)]
    pub fn sparse_domain_identity_ignores_values(&self) -> bool {
        self.value.sparse_domain_identity_ignores_values
    }
    /// 不同值域碰撞 / Whether different domains collide.
    #[wasm_bindgen(js_name = differentDomainsCollide)]
    pub fn different_domains_collide(&self) -> bool { self.value.different_domains_collide }
    /// 不同数值不碰撞 / Whether different numbers differ.
    #[wasm_bindgen(js_name = differentNumbersDoNotCollide)]
    pub fn different_numbers_do_not_collide(&self) -> bool {
        self.value.different_numbers_do_not_collide
    }
    /// 极性进身份 / Whether polarity is part of the identity.
    #[wasm_bindgen(js_name = polarityIsPartOfTheIdentity)]
    pub fn polarity_is_part_of_the_identity(&self) -> bool {
        self.value.polarity_is_part_of_the_identity
    }
    /// 值域排序去重 / Whether domains are sorted and deduplicated.
    #[wasm_bindgen(js_name = domainValuesAreNormalized)]
    pub fn domain_values_are_normalized(&self) -> bool { self.value.domain_values_are_normalized }
    /// 分隔符不构成歧义 / Whether separators cause no ambiguity.
    #[wasm_bindgen(js_name = separatorsAreUnambiguous)]
    pub fn separators_are_unambiguous(&self) -> bool { self.value.separators_are_unambiguous }
    /// 映射恰好覆盖一次 / Whether the mapping covers exactly once.
    #[wasm_bindgen(js_name = mappingMustCoverExactlyOnce)]
    pub fn mapping_must_cover_exactly_once(&self) -> bool {
        self.value.mapping_must_cover_exactly_once
    }
}

