/// 极性编码结论的独立 reader（续挖：`solver/logic_based_benders`）。
/// Independent reader for the polarity-encoding verdict (continuation).
#[wasm_bindgen]
pub struct PolarityReport { value: ospf_rust_bridge::PolarityReport }

#[wasm_bindgen]
impl PolarityReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<PolarityReport, JsValue> {
        if json.len() > 1024 * 1024 { return Err(error("polarity report exceeds 1 MiB")); }
        let value: ospf_rust_bridge::PolarityReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：二进制 no-good 的系数只能是 ±1 且不全同号以外还要与 1 的个数自洽；
        // 右端项必须等于 1 减 1 的个数；编码条数必须等于系数条数；边行的右端项必须与另一侧的关系方向配对。
        // Read-side re-checks: the binary coefficients are ±1 and agree with the ones count; the rhs equals 1 minus the
        // ones; the encoding size equals the coefficient count; and a side row's rhs pairs with its sense.
        if value.no_good.terms.is_empty() {
            return Err(error("polarity report carries an empty no-good"));
        }
        if value.no_good.sense != "greaterOrEqual" {
            return Err(error("polarity report mislabels the no-good sense"));
        }
        if value.no_good.terms.iter().any(|term| !(term.coefficient == 1.0 || term.coefficient == -1.0)) {
            return Err(error("polarity report carries a non-polarity coefficient"));
        }
        let ones = value.no_good.terms.iter().filter(|term| term.coefficient == -1.0).count() as u64;
        if ones != value.ones {
            return Err(error("polarity report disagrees on the ones count"));
        }
        if value.no_good.rhs != 1.0 - ones as f64 {
            return Err(error("polarity report disagrees on the no-good rhs"));
        }
        if value.encoding_count as usize != value.no_good.terms.len() {
            return Err(error("polarity report disagrees between the encoding and the coefficients"));
        }
        if value.no_good.id.trim().is_empty() || !value.no_good.id.starts_with("logic/no-good/") {
            return Err(error("polarity report carries a malformed no-good ID"));
        }
        for family in &value.families {
            if family.lower_side.sense != "lessOrEqual" || family.upper_side.sense != "greaterOrEqual"
                || family.at_most_one.sense != "lessOrEqual"
                || family.require_difference.sense != "greaterOrEqual"
            {
                return Err(error("polarity report mislabels a family row sense"));
            }
            if family.lower_side.rhs < family.upper_side.rhs {
                return Err(error("polarity report has its side rows the wrong way round"));
            }
            if family.at_most_one.rhs != 1.0 || family.require_difference.rhs != 1.0 {
                return Err(error("polarity report disagrees on a unit row's rhs"));
            }
            if family.lower_side.terms.len() != 2 || family.upper_side.terms.len() != 2
                || family.at_most_one.terms.len() != 2
            {
                return Err(error("polarity report carries a family row with the wrong width"));
            }
            if family.require_difference.terms.len() < family.at_most_one.terms.len() {
                return Err(error("polarity report gives require-difference too few auxiliaries"));
            }
        }
        if !value.coefficients_are_the_negated_bits || !value.rhs_is_one_minus_the_ones
            || !value.all_ones_rhs_is_negative || !value.id_is_a_pure_function_of_the_assignment
            || !value.encoding_holds_every_variable || !value.side_rows_carry_domain_bounds
            || !value.at_most_one_is_a_pair || !value.require_difference_spans_every_auxiliary
            || !value.unit_rows_use_rhs_one
        {
            return Err(error("polarity report admits a broken encoding finding"));
        }
        Ok(PolarityReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// no-good 的 cut ID / The no-good's cut ID.
    #[wasm_bindgen(js_name = noGoodId)]
    pub fn no_good_id(&self) -> String { self.value.no_good.id.clone() }
    /// no-good 的右端项 / The no-good's rhs.
    #[wasm_bindgen(js_name = noGoodRhs)]
    pub fn no_good_rhs(&self) -> f64 { self.value.no_good.rhs }
    /// no-good 的关系方向 / The no-good's sense.
    #[wasm_bindgen(js_name = noGoodSense)]
    pub fn no_good_sense(&self) -> String { self.value.no_good.sense.clone() }
    /// no-good 的系数条数 / The no-good's coefficient count.
    #[wasm_bindgen(js_name = noGoodTermCount)]
    pub fn no_good_term_count(&self) -> u32 {
        u32::try_from(self.value.no_good.terms.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个系数的变量 / The variable of term `position`.
    #[wasm_bindgen(js_name = noGoodTermVariable)]
    pub fn no_good_term_variable(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.term(position)?.variable.clone())
    }
    /// 第 `position` 个系数的值 / The coefficient of term `position`.
    #[wasm_bindgen(js_name = noGoodTermCoefficient)]
    pub fn no_good_term_coefficient(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.term(position)?.coefficient)
    }
    /// 编码里的赋值条数 / The encoding's assignment count.
    #[wasm_bindgen(js_name = encodingCount)]
    pub fn encoding_count(&self) -> f64 { self.value.encoding_count as f64 }
    /// 1 的个数 / The ones count.
    #[wasm_bindgen(js_name = ones)]
    pub fn ones(&self) -> f64 { self.value.ones as f64 }
    /// 家族个数 / The number of families.
    #[wasm_bindgen(js_name = familyCount)]
    pub fn family_count(&self) -> u32 {
        u32::try_from(self.value.families.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个家族 lower 行的右端项 / The lower row's rhs of family `position`.
    #[wasm_bindgen(js_name = familyLowerRhs)]
    pub fn family_lower_rhs(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.family(position)?.lower_side.rhs)
    }
    /// 第 `position` 个家族 upper 行的右端项 / The upper row's rhs of family `position`.
    #[wasm_bindgen(js_name = familyUpperRhs)]
    pub fn family_upper_rhs(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.family(position)?.upper_side.rhs)
    }
    /// 第 `position` 个家族 at-most-one 行的右端项 / The at-most-one row's rhs.
    #[wasm_bindgen(js_name = familyAtMostOneRhs)]
    pub fn family_at_most_one_rhs(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.family(position)?.at_most_one.rhs)
    }
    /// 第 `position` 个家族 at-most-one 行的宽度 / The at-most-one row's width.
    #[wasm_bindgen(js_name = familyAtMostOneWidth)]
    pub fn family_at_most_one_width(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.family(position)?.at_most_one.terms.len() as f64)
    }
    /// 第 `position` 个家族 require-difference 行的宽度 / The require-difference row's width.
    #[wasm_bindgen(js_name = familyRequireDifferenceWidth)]
    pub fn family_require_difference_width(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.family(position)?.require_difference.terms.len() as f64)
    }
    /// 第 `position` 个家族 lower 行各项的变量名 / The lower row's variables of family `position`.
    #[wasm_bindgen(js_name = familyLowerVariables)]
    pub fn family_lower_variables(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.family(position)?.lower_side.terms.iter()
            .map(|term| term.variable.as_str()).collect::<Vec<_>>().join(","))
    }
    /// 第 `position` 个家族 lower 行各项的系数 / The lower row's coefficients of family `position`.
    #[wasm_bindgen(js_name = familyLowerCoefficients)]
    pub fn family_lower_coefficients(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.family(position)?.lower_side.terms.iter()
            .map(|term| term.coefficient.to_string()).collect::<Vec<_>>().join(","))
    }
    /// 系数是取反的位 / Whether coefficients are the negated bits.
    #[wasm_bindgen(js_name = coefficientsAreTheNegatedBits)]
    pub fn coefficients_are_the_negated_bits(&self) -> bool {
        self.value.coefficients_are_the_negated_bits
    }
    /// 右端项是 1 减 1 的个数 / Whether the rhs is 1 minus the ones.
    #[wasm_bindgen(js_name = rhsIsOneMinusTheOnes)]
    pub fn rhs_is_one_minus_the_ones(&self) -> bool { self.value.rhs_is_one_minus_the_ones }
    /// 全 1 时右端项为负 / Whether an all-ones assignment gives a negative rhs.
    #[wasm_bindgen(js_name = allOnesRhsIsNegative)]
    pub fn all_ones_rhs_is_negative(&self) -> bool { self.value.all_ones_rhs_is_negative }
    /// ID 只取决于被排除的赋值 / Whether the ID depends only on the assignment.
    #[wasm_bindgen(js_name = idIsAPureFunctionOfTheAssignment)]
    pub fn id_is_a_pure_function_of_the_assignment(&self) -> bool {
        self.value.id_is_a_pure_function_of_the_assignment
    }
    /// 编码里存完整赋值 / Whether the encoding stores the complete assignment.
    #[wasm_bindgen(js_name = encodingHoldsEveryVariable)]
    pub fn encoding_holds_every_variable(&self) -> bool {
        self.value.encoding_holds_every_variable
    }
    /// 边行右端项就是值域边界 / Whether a side row's rhs is a domain bound.
    #[wasm_bindgen(js_name = sideRowsCarryDomainBounds)]
    pub fn side_rows_carry_domain_bounds(&self) -> bool { self.value.side_rows_carry_domain_bounds }
    /// `atMostOne` 只用两个辅助变量 / Whether `atMostOne` uses two auxiliaries.
    #[wasm_bindgen(js_name = atMostOneIsAPair)]
    pub fn at_most_one_is_a_pair(&self) -> bool { self.value.at_most_one_is_a_pair }
    /// `requireDifference` 覆盖全部 `2n` / Whether `requireDifference` spans all `2n`.
    #[wasm_bindgen(js_name = requireDifferenceSpansEveryAuxiliary)]
    pub fn require_difference_spans_every_auxiliary(&self) -> bool {
        self.value.require_difference_spans_every_auxiliary
    }
    /// 两条无辅助身份的边行都用 rhs 1.0 / Whether both unit rows use rhs 1.0.
    #[wasm_bindgen(js_name = unitRowsUseRhsOne)]
    pub fn unit_rows_use_rhs_one(&self) -> bool { self.value.unit_rows_use_rhs_one }
}

