/// 活动性报告自洽性结论的独立 reader（续挖：`analysis/activity`）。
/// Independent reader for the activity-report consistency verdict (continuation).
#[wasm_bindgen]
pub struct ActivityReportVerdict { value: ospf_rust_bridge::ActivityReportVerdict }

#[wasm_bindgen]
impl ActivityReportVerdict {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<ActivityReportVerdict, JsValue> {
        if json.len() > 64 * 1024 { return Err(error("activity report verdict exceeds 64 KiB")); }
        let value: ospf_rust_bridge::ActivityReportVerdict = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：被接受时不得带错误消息；被拒时必须带非空消息。
        // Read-side re-checks: an accepted verdict carries no message, and a refusal must carry a non-blank one.
        if value.accepted {
            if value.error.is_some() {
                return Err(error("activity report verdict was accepted yet carries an error"));
            }
        } else if value.error.as_deref().is_none_or(|message| message.trim().is_empty()) {
            return Err(error("activity report verdict was refused without a message"));
        }
        if !value.aggregates_are_recomputed || !value.duplicate_groups_are_refused
            || !value.numbers_only_check_finiteness || !value.status_is_not_cross_checked
            || !value.satisfied_is_not_cross_checked || !value.identities_are_checked
        {
            return Err(error("activity report verdict admits a broken consistency finding"));
        }
        Ok(ActivityReportVerdict { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// `validate()` 是否通过 / Whether `validate()` passed.
    #[wasm_bindgen(js_name = accepted)]
    pub fn accepted(&self) -> bool { self.value.accepted }
    /// 失败消息 / The failure message.
    #[wasm_bindgen(js_name = error)]
    pub fn error_message(&self) -> Option<String> { self.value.error.clone() }
    /// 聚合字段被重算比对 / Whether the aggregates are recomputed.
    #[wasm_bindgen(js_name = aggregatesAreRecomputed)]
    pub fn aggregates_are_recomputed(&self) -> bool { self.value.aggregates_are_recomputed }
    /// 重复的组被拒 / Whether duplicate groups are refused.
    #[wasm_bindgen(js_name = duplicateGroupsAreRefused)]
    pub fn duplicate_groups_are_refused(&self) -> bool { self.value.duplicate_groups_are_refused }
    /// 数值只查有限性 / Whether numbers are only checked for finiteness.
    #[wasm_bindgen(js_name = numbersOnlyCheckFiniteness)]
    pub fn numbers_only_check_finiteness(&self) -> bool {
        self.value.numbers_only_check_finiteness
    }
    /// `status` 不交叉校验 / Whether `status` is not cross-checked.
    #[wasm_bindgen(js_name = statusIsNotCrossChecked)]
    pub fn status_is_not_cross_checked(&self) -> bool { self.value.status_is_not_cross_checked }
    /// `satisfied` 不交叉校验 / Whether `satisfied` is not cross-checked.
    #[wasm_bindgen(js_name = satisfiedIsNotCrossChecked)]
    pub fn satisfied_is_not_cross_checked(&self) -> bool {
        self.value.satisfied_is_not_cross_checked
    }
    /// 身份被校验 / Whether identities are checked.
    #[wasm_bindgen(js_name = identitiesAreChecked)]
    pub fn identities_are_checked(&self) -> bool { self.value.identities_are_checked }
}

/// 辅助域校验结论的独立 reader（续挖：`solver/logic_based_benders`）。
/// Independent reader for the auxiliary-domain verdict (continuation).
#[wasm_bindgen]
pub struct AuxiliaryDomainReport { value: ospf_rust_bridge::AuxiliaryDomainReport }

#[wasm_bindgen]
impl AuxiliaryDomainReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<AuxiliaryDomainReport, JsValue> {
        if json.len() > 256 * 1024 { return Err(error("auxiliary domain report exceeds 256 KiB")); }
        let value: ospf_rust_bridge::AuxiliaryDomainReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：被接受的条目不得带错误、被拒的必须带非空消息；保留的 ID 数必须等于 `keptCount`；
        // 一次性结果与它的消息必须互补（接受则无消息、拒绝则必有消息）。
        // Read-side re-checks: an accepted outcome carries no message and a refusal must carry a non-blank one; the kept IDs
        // equal `keptCount`; and a combined verdict and its message are complementary (accepted means no message, refused
        // means one).
        for outcome in &value.outcomes {
            if outcome.accepted {
                if outcome.error.is_some() {
                    return Err(error("auxiliary domain report accepted a declaration yet carries an error"));
                }
            } else if outcome.error.as_deref().is_none_or(|message| message.trim().is_empty()) {
                return Err(error("auxiliary domain report refused a declaration without a message"));
            }
            if outcome.id.is_empty() {
                return Err(error("auxiliary domain report carries an empty declaration ID"));
            }
        }
        if value.kept_count != value.kept_ids.len() as u64 {
            return Err(error("auxiliary domain report disagrees on the kept count"));
        }
        if value.combined_accepted.is_some()
            && value.combined_error.is_some() == value.combined_accepted.unwrap_or(false)
        {
            return Err(error("auxiliary domain report mislabels the combined verdict"));
        }
        if !value.two_to_the_53_passes || !value.beyond_the_exact_range_is_refused
            || !value.inverted_bounds_are_refused || !value.binary_is_unchecked
            || !value.blank_ids_are_refused || !value.duplicate_ids_are_refused
            || !value.normalize_keeps_the_declarations
        {
            return Err(error("auxiliary domain report admits a broken domain finding"));
        }
        Ok(AuxiliaryDomainReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 逐条结果条数 / The outcome count.
    #[wasm_bindgen(js_name = outcomeCount)]
    pub fn outcome_count(&self) -> u32 {
        u32::try_from(self.value.outcomes.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 条的 ID / The ID of outcome `position`.
    #[wasm_bindgen(js_name = idAt)]
    pub fn id_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.outcome(position)?.id.clone())
    }
    /// 第 `position` 条是否被接受 / Whether outcome `position` was accepted.
    #[wasm_bindgen(js_name = acceptedAt)]
    pub fn accepted_at(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.outcome(position)?.accepted)
    }
    /// 第 `position` 条的失败消息 / The failure message of outcome `position`.
    #[wasm_bindgen(js_name = errorAt)]
    pub fn error_at(&self, position: u32) -> Result<Option<String>, JsValue> {
        Ok(self.outcome(position)?.error.clone())
    }
    /// 一次性放全部时是否被接受 / Whether the combined cut was accepted.
    #[wasm_bindgen(js_name = combinedAccepted)]
    pub fn combined_accepted(&self) -> Option<bool> { self.value.combined_accepted }
    /// 一次性放全部时的失败消息 / The combined failure message.
    #[wasm_bindgen(js_name = combinedError)]
    pub fn combined_error(&self) -> Option<String> { self.value.combined_error.clone() }
    /// `normalize()` 之后保留的条数 / The kept declaration count.
    #[wasm_bindgen(js_name = keptCount)]
    pub fn kept_count(&self) -> f64 { self.value.kept_count as f64 }
    /// 保留的 ID 条数 / The kept ID count.
    #[wasm_bindgen(js_name = keptIdCount)]
    pub fn kept_id_count(&self) -> u32 {
        u32::try_from(self.value.kept_ids.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个保留的 ID / The kept ID at `position`.
    #[wasm_bindgen(js_name = keptIdAt)]
    pub fn kept_id_at(&self, position: u32) -> Result<String, JsValue> {
        self.value.kept_ids.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("kept index out of range"))
    }
    /// 恰好 `2^53` 被放行 / Whether exactly `2^53` passes.
    #[wasm_bindgen(js_name = twoToThe53Passes)]
    pub fn two_to_the_53_passes(&self) -> bool { self.value.two_to_the_53_passes }
    /// `2^53 + 1` 被拒 / Whether `2^53 + 1` is refused.
    #[wasm_bindgen(js_name = beyondTheExactRangeIsRefused)]
    pub fn beyond_the_exact_range_is_refused(&self) -> bool {
        self.value.beyond_the_exact_range_is_refused
    }
    /// 界颠倒被拒 / Whether inverted bounds are refused.
    #[wasm_bindgen(js_name = invertedBoundsAreRefused)]
    pub fn inverted_bounds_are_refused(&self) -> bool { self.value.inverted_bounds_are_refused }
    /// `binary` 域不参与校验 / Whether the `binary` domain is unchecked.
    #[wasm_bindgen(js_name = binaryIsUnchecked)]
    pub fn binary_is_unchecked(&self) -> bool { self.value.binary_is_unchecked }
    /// 空白 ID 被拒 / Whether blank IDs are refused.
    #[wasm_bindgen(js_name = blankIdsAreRefused)]
    pub fn blank_ids_are_refused(&self) -> bool { self.value.blank_ids_are_refused }
    /// 重复 ID 是另一条报错 / Whether a duplicate ID raises a different error.
    #[wasm_bindgen(js_name = duplicateIdsAreRefused)]
    pub fn duplicate_ids_are_refused(&self) -> bool { self.value.duplicate_ids_are_refused }
    /// `normalize()` 原样保留声明 / Whether `normalize()` keeps the declarations verbatim.
    #[wasm_bindgen(js_name = normalizeKeepsTheDeclarations)]
    pub fn normalize_keeps_the_declarations(&self) -> bool {
        self.value.normalize_keeps_the_declarations
    }
}

