/// 更新赋值组合结论的独立 reader（续挖：`persistence/expression`）。
/// Independent reader for the assignment-composition verdict (continuation).
#[wasm_bindgen]
pub struct AssignmentCompositionReport { value: ospf_rust_bridge::AssignmentCompositionReport }

#[wasm_bindgen]
impl AssignmentCompositionReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<AssignmentCompositionReport, JsValue> {
        if json.len() > 256 * 1024 { return Err(error("assignment composition report exceeds 256 KiB")); }
        let value: ospf_rust_bridge::AssignmentCompositionReport =
            serde_json::from_str(json).map_err(error)?;
        // 读侧复核：`variant` 必须在三个名字里；`set-null` 的值种类必须是 `none`、`set-from-expression` 必须是
        // `expression`；`empty` 必须等于条数为零；`ofPath` 的段数必须等于 `ofSegments` 的长度。
        // Read-side re-checks: `variant` is one of the three names; `set-null` must report `none` and
        // `set-from-expression` must report `expression`; `empty` equals "no items"; and the `ofPath` segment count equals
        // the length of `ofSegments`.
        for item in &value.items {
            match item.variant.as_str() {
                "set-value" => {
                    if matches!(item.value_kind.as_str(), "none" | "expression") {
                        return Err(error("assignment composition report mismatches a set-value kind"));
                    }
                }
                "set-null" => {
                    if item.value_kind != "none" {
                        return Err(error("assignment composition report mismatches a set-null kind"));
                    }
                }
                "set-from-expression" => {
                    if item.value_kind != "expression" {
                        return Err(error(
                            "assignment composition report mismatches a set-from-expression kind"));
                    }
                }
                _ => return Err(error("assignment composition report has an unknown variant")),
            }
        }
        if value.empty != value.items.is_empty() {
            return Err(error("assignment composition report disagrees on emptiness"));
        }
        let of_segment_count = if value.of_path.is_empty() { 0 }
            else { value.of_path.split('.').count() };
        if of_segment_count != value.of_segments.len() {
            return Err(error("assignment composition report disagrees on the joined segments"));
        }
        if !value.the_order_is_fifo_and_add_matches_then || !value.the_same_path_is_not_merged
            || !value.null_value_and_set_null_differ || !value.three_validation_strengths
            || !value.of_does_not_validate_segments || !value.a_blank_path_has_no_segments
            || !value.identifiers_are_unicode_aware
        {
            return Err(error("assignment composition report admits a broken composition finding"));
        }
        Ok(AssignmentCompositionReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 赋值项条数 / The assignment-item count.
    #[wasm_bindgen(js_name = itemCount)]
    pub fn item_count(&self) -> u32 {
        u32::try_from(self.value.items.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 条的路径 / The path at `position`.
    #[wasm_bindgen(js_name = pathAt)]
    pub fn path_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.item(position)?.path.clone())
    }
    /// 第 `position` 条的变体 / The variant at `position`.
    #[wasm_bindgen(js_name = variantAt)]
    pub fn variant_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.item(position)?.variant.clone())
    }
    /// 第 `position` 条的值种类 / The value kind at `position`.
    #[wasm_bindgen(js_name = valueKindAt)]
    pub fn value_kind_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.item(position)?.value_kind.clone())
    }
    /// 集合是否为空 / Whether the set is empty.
    #[wasm_bindgen(js_name = empty)]
    pub fn empty(&self) -> bool { self.value.empty }
    /// 空集合追加空集合之后是否仍为空 / Whether an empty set stays empty after appending one.
    #[wasm_bindgen(js_name = emptyAfterThen)]
    pub fn empty_after_then(&self) -> bool { self.value.empty_after_then }
    /// 路径条数 / The path count.
    #[wasm_bindgen(js_name = pathCount)]
    pub fn path_count(&self) -> u32 {
        u32::try_from(self.value.paths.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 条路径的原文本 / The raw text at `position`.
    #[wasm_bindgen(js_name = rawAt)]
    pub fn raw_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.path(position)?.raw.clone())
    }
    /// 第 `position` 条路径的 `new` 结果 / The `new` result at `position`.
    #[wasm_bindgen(js_name = fromNewAt)]
    pub fn from_new_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.path(position)?.from_new.clone())
    }
    /// 第 `position` 条路径的 `parse` 结果 / The `parse` result at `position`.
    #[wasm_bindgen(js_name = fromParseAt)]
    pub fn from_parse_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.path(position)?.from_parse.clone())
    }
    /// 第 `position` 条路径的 `tryParse` 是否成功 / Whether `tryParse` succeeded at `position`.
    #[wasm_bindgen(js_name = parsedAt)]
    pub fn parsed_at(&self, position: u32) -> Result<bool, JsValue> {
        Ok(self.path(position)?.parsed)
    }
    /// 第 `position` 条路径的段数 / The segment count at `position`.
    #[wasm_bindgen(js_name = segmentCountAt)]
    pub fn segment_count_at(&self, position: u32) -> Result<u32, JsValue> {
        Ok(u32::try_from(self.path(position)?.segments.len()).unwrap_or(u32::MAX))
    }
    /// 第 `position` 条路径第 `segment` 段 / Segment `segment` at `position`.
    #[wasm_bindgen(js_name = segmentAt)]
    pub fn segment_at(&self, position: u32, segment: u32) -> Result<String, JsValue> {
        self.path(position)?.segments
            .get(usize::try_from(segment).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("segment index out of range"))
    }
    /// `of` 拼出来的路径 / The path `of` produced.
    #[wasm_bindgen(js_name = ofPath)]
    pub fn of_path(&self) -> String { self.value.of_path.clone() }
    /// `of` 的段数 / The `of` segment count.
    #[wasm_bindgen(js_name = ofSegmentCount)]
    pub fn of_segment_count(&self) -> u32 {
        u32::try_from(self.value.of_segments.len()).unwrap_or(u32::MAX)
    }
    /// `of` 的第 `segment` 段 / Segment `segment` of the `of` path.
    #[wasm_bindgen(js_name = ofSegmentAt)]
    pub fn of_segment_at(&self, segment: u32) -> Result<String, JsValue> {
        self.value.of_segments.get(usize::try_from(segment).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("segment index out of range"))
    }
    /// 顺序是 FIFO 且 `Add` 等价于 `then` / Whether the order is FIFO and `Add` matches `then`.
    #[wasm_bindgen(js_name = theOrderIsFifoAndAddMatchesThen)]
    pub fn the_order_is_fifo_and_add_matches_then(&self) -> bool {
        self.value.the_order_is_fifo_and_add_matches_then
    }
    /// 同一路径不被合并 / Whether the same path is left unmerged.
    #[wasm_bindgen(js_name = theSamePathIsNotMerged)]
    pub fn the_same_path_is_not_merged(&self) -> bool { self.value.the_same_path_is_not_merged }
    /// `setNull` 与 `set(_, null)` 不同 / Whether `setNull` and `set(_, null)` differ.
    #[wasm_bindgen(js_name = nullValueAndSetNullDiffer)]
    pub fn null_value_and_set_null_differ(&self) -> bool { self.value.null_value_and_set_null_differ }
    /// 三种校验强度 / Whether the three validation strengths hold.
    #[wasm_bindgen(js_name = threeValidationStrengths)]
    pub fn three_validation_strengths(&self) -> bool { self.value.three_validation_strengths }
    /// `of` 不校验分段 / Whether `of` skips segment validation.
    #[wasm_bindgen(js_name = ofDoesNotValidateSegments)]
    pub fn of_does_not_validate_segments(&self) -> bool { self.value.of_does_not_validate_segments }
    /// 空白路径没有分段 / Whether a blank path has no segments.
    #[wasm_bindgen(js_name = aBlankPathHasNoSegments)]
    pub fn a_blank_path_has_no_segments(&self) -> bool { self.value.a_blank_path_has_no_segments }
    /// 标识符判定是 Unicode 的 / Whether identifier rules are Unicode-aware.
    #[wasm_bindgen(js_name = identifiersAreUnicodeAware)]
    pub fn identifiers_are_unicode_aware(&self) -> bool { self.value.identifiers_are_unicode_aware }
}

