/// 批量导出结论的独立 reader（续挖：`model/intermediate`）。
/// Independent reader for the batch export verdict (continuation).
#[wasm_bindgen]
pub struct DumpBatchReport { value: ospf_rust_bridge::DumpBatchReport }

#[wasm_bindgen]
impl DumpBatchReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<DumpBatchReport, JsValue> {
        if json.len() > 256 * 1024 { return Err(error("dump batch report exceeds 256 KiB")); }
        let value: ospf_rust_bridge::DumpBatchReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：失败必须带消息、成功不得带；`bytes` 必须与 `content` 的长度一致；
        // 失败时留下的文件必须是既有文件名的子集。
        // Read-side re-checks: a failure carries a message and a success does not; `bytes` agrees with the content length;
        // and the leftovers of a failure are a subset of the written names.
        if value.failed {
            if value.error.as_deref().is_none_or(|message| message.trim().is_empty()) {
                return Err(error("dump batch report failed without a message"));
            }
        } else if value.error.is_some() {
            return Err(error("dump batch report succeeded yet carries an error"));
        }
        for row in &value.files {
            if row.bytes != row.content.len() as u64 {
                return Err(error("dump batch report disagrees between bytes and content"));
            }
            if row.name.trim().is_empty() {
                return Err(error("dump batch report has a blank file name"));
            }
        }
        let names = value.files.iter().map(|row| row.name.as_str()).collect::<Vec<_>>();
        if value.leftovers.iter().any(|name| !names.contains(&name.as_str())) {
            return Err(error("dump batch report kept a leftover that was never written"));
        }
        if !value.concurrent_matches_serial || !value.a_single_entry_is_always_serial
            || !value.opm_ignores_the_dump_options || !value.errors_carry_the_path
            || !value.a_failure_leaves_earlier_files_behind
            || !value.concurrent_errors_propagate || !value.the_format_ignores_the_extension
        {
            return Err(error("dump batch report admits a broken dispatch finding"));
        }
        Ok(DumpBatchReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> { serde_json::to_string(&self.value).map_err(error) }
    /// 失败消息 / The failure message.
    #[wasm_bindgen(js_name = error)]
    pub fn error_message(&self) -> Option<String> { self.value.error.clone() }
    /// 是否失败 / Whether the batch failed.
    #[wasm_bindgen(js_name = failed)]
    pub fn failed(&self) -> bool { self.value.failed }
    /// 文件条数 / The file count.
    #[wasm_bindgen(js_name = fileCount)]
    pub fn file_count(&self) -> u32 {
        u32::try_from(self.value.files.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个文件名 / The file name at `position`.
    #[wasm_bindgen(js_name = fileNameAt)]
    pub fn file_name_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.file(position)?.name.clone())
    }
    /// 第 `position` 个文件的字数 / The file content length at `position`.
    #[wasm_bindgen(js_name = fileBytesAt)]
    pub fn file_bytes_at(&self, position: u32) -> Result<f64, JsValue> {
        Ok(self.file(position)?.bytes as f64)
    }
    /// 第 `position` 个文件的内容 / The file content at `position`.
    #[wasm_bindgen(js_name = fileContentAt)]
    pub fn file_content_at(&self, position: u32) -> Result<String, JsValue> {
        Ok(self.file(position)?.content.clone())
    }
    /// 失败后仍留下的文件名 / The files left behind.
    #[wasm_bindgen(js_name = leftoverCount)]
    pub fn leftover_count(&self) -> u32 {
        u32::try_from(self.value.leftovers.len()).unwrap_or(u32::MAX)
    }
    /// 第 `position` 个残留文件名 / The leftover name at `position`.
    #[wasm_bindgen(js_name = leftoverAt)]
    pub fn leftover_at(&self, position: u32) -> Result<String, JsValue> {
        self.value.leftovers.get(usize::try_from(position).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("leftover index out of range"))
    }
    /// `concurrent` 只改调度 / Whether `concurrent` only changes scheduling.
    #[wasm_bindgen(js_name = concurrentMatchesSerial)]
    pub fn concurrent_matches_serial(&self) -> bool { self.value.concurrent_matches_serial }
    /// 单条目永远串行 / Whether a single entry is always serial.
    #[wasm_bindgen(js_name = aSingleEntryIsAlwaysSerial)]
    pub fn a_single_entry_is_always_serial(&self) -> bool {
        self.value.a_single_entry_is_always_serial
    }
    /// `OPM` 忽略转储选项 / Whether `OPM` ignores the dump options.
    #[wasm_bindgen(js_name = opmIgnoresTheDumpOptions)]
    pub fn opm_ignores_the_dump_options(&self) -> bool { self.value.opm_ignores_the_dump_options }
    /// 错误带路径 / Whether errors carry the path.
    #[wasm_bindgen(js_name = errorsCarryThePath)]
    pub fn errors_carry_the_path(&self) -> bool { self.value.errors_carry_the_path }
    /// 失败不回滚 / Whether a failure leaves earlier files.
    #[wasm_bindgen(js_name = aFailureLeavesEarlierFilesBehind)]
    pub fn a_failure_leaves_earlier_files_behind(&self) -> bool {
        self.value.a_failure_leaves_earlier_files_behind
    }
    /// 并发错误仍传播 / Whether concurrent errors propagate.
    #[wasm_bindgen(js_name = concurrentErrorsPropagate)]
    pub fn concurrent_errors_propagate(&self) -> bool { self.value.concurrent_errors_propagate }
    /// 格式与后缀无关 / Whether the format ignores the extension.
    #[wasm_bindgen(js_name = theFormatIgnoresTheExtension)]
    pub fn the_format_ignores_the_extension(&self) -> bool {
        self.value.the_format_ignores_the_extension
    }
}

