/// 冲突提取层级选择结论的独立 reader（续挖：`analysis/activation.rs`）。
/// Independent reader for the tier-selection verdict (continuation).
#[wasm_bindgen]
pub struct TierSelectionReport { value: ospf_rust_bridge::TierSelectionReport }

#[wasm_bindgen]
impl TierSelectionReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<TierSelectionReport, JsValue> {
        if json.len() > 64 * 1024 { return Err(error("tier selection report exceeds 64 KiB")); }
        let value: ospf_rust_bridge::TierSelectionReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：层级名在四词表里；`isNative` 与层级名必须自洽（只有 `native-unsat-core` 原生）；
        // `isAvailable` 与层级名自洽（只有 `unavailable` 不可用）；三个支持级别的词表检查。
        // Read-side re-checks: the tier name comes from a four-word vocabulary; `isNative` agrees with the name (only
        // `native-unsat-core` is native); `isAvailable` agrees too (only `unavailable` is unusable); the three support
        // levels are vocabulary-checked.
        if !matches!(value.selected.as_str(), "native-unsat-core" | "assumption-extraction"
            | "repeated-solving" | "unavailable")
        {
            return Err(error("tier selection report has an unknown tier name"));
        }
        if value.selected_is_native != (value.selected == "native-unsat-core") {
            return Err(error("tier selection report disagrees between isNative and the tier name"));
        }
        if value.selected_is_available != (value.selected != "unavailable") {
            return Err(error("tier selection report disagrees between isAvailable and the tier name"));
        }
        for level in [&value.native_unsat_core_support, &value.assumption_solving_support,
            &value.conflict_support]
        {
            if !matches!(level.as_str(), "supported" | "conditional" | "unsupported") {
                return Err(error("tier selection report has an unknown support level"));
            }
        }
        // "选中原生层但标志为假"是合法状态（覆盖造成的脱钩），所以不额外校验。 
        // "Selected the native tier with a false flag" is legal (an override causes the decoupling), so it is not
        // additionally checked.
        if !value.the_order_is_the_priority
            || !value.only_supported_is_selected
            || !value.a_fallback_only_backend_lands_on_repeated_solving
            || !value.an_override_can_upgrade_the_selection
            || !value.an_override_can_disable_the_fallback
            || !value.selecting_the_native_tier_does_not_make_it_native
            || !value.the_four_tiers_have_exact_predicates
            || !value.the_stable_names_are_four_words
        {
            return Err(error("tier selection report admits a broken selection rule"));
        }
        Ok(TierSelectionReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> {
        serde_json::to_string(&self.value).map_err(error)
    }
    /// 选中的层级名 / The selected tier's name.
    #[wasm_bindgen(js_name = selected)]
    pub fn selected(&self) -> String { self.value.selected.clone() }
    /// 选中层是否原生 / Whether the selected tier is native.
    #[wasm_bindgen(js_name = selectedIsNative)]
    pub fn selected_is_native(&self) -> bool { self.value.selected_is_native }
    /// 选中层是否可用 / Whether the selected tier is available.
    #[wasm_bindgen(js_name = selectedIsAvailable)]
    pub fn selected_is_available(&self) -> bool { self.value.selected_is_available }
    /// `is_native(NativeUnsatCore)` 的读数 / The native flag.
    #[wasm_bindgen(js_name = nativeUnsatCoreFlag)]
    pub fn native_unsat_core_flag(&self) -> bool { self.value.native_unsat_core_flag }
    /// `support(NativeUnsatCore)` 的读数 / `support(NativeUnsatCore)`.
    #[wasm_bindgen(js_name = nativeUnsatCoreSupport)]
    pub fn native_unsat_core_support(&self) -> String {
        self.value.native_unsat_core_support.clone()
    }
    /// `support(AssumptionSolving)` 的读数 / `support(AssumptionSolving)`.
    #[wasm_bindgen(js_name = assumptionSolvingSupport)]
    pub fn assumption_solving_support(&self) -> String {
        self.value.assumption_solving_support.clone()
    }
    /// `support(Conflict)` 的读数 / `support(Conflict)`.
    #[wasm_bindgen(js_name = conflictSupport)]
    pub fn conflict_support(&self) -> String { self.value.conflict_support.clone() }
    /// 顺序即优先级 / Whether the order is the priority.
    #[wasm_bindgen(js_name = theOrderIsThePriority)]
    pub fn the_order_is_the_priority(&self) -> bool { self.value.the_order_is_the_priority }
    /// 只有 `Supported` 能被选中 / Whether only `Supported` is selected.
    #[wasm_bindgen(js_name = onlySupportedIsSelected)]
    pub fn only_supported_is_selected(&self) -> bool { self.value.only_supported_is_selected }
    /// 只有 fallback 的后端走 `RepeatedSolving` / Whether a fallback-only backend lands on `RepeatedSolving`.
    #[wasm_bindgen(js_name = aFallbackOnlyBackendLandsOnRepeatedSolving)]
    pub fn a_fallback_only_backend_lands_on_repeated_solving(&self) -> bool {
        self.value.a_fallback_only_backend_lands_on_repeated_solving
    }
    /// 覆盖能抬升选择 / Whether an override can upgrade the selection.
    #[wasm_bindgen(js_name = anOverrideCanUpgradeTheSelection)]
    pub fn an_override_can_upgrade_the_selection(&self) -> bool {
        self.value.an_override_can_upgrade_the_selection
    }
    /// 覆盖能关掉 fallback / Whether an override can disable the fallback.
    #[wasm_bindgen(js_name = anOverrideCanDisableTheFallback)]
    pub fn an_override_can_disable_the_fallback(&self) -> bool {
        self.value.an_override_can_disable_the_fallback
    }
    /// 选中原生层不等于原生标志为真 / Whether selecting the native tier leaves the flag false.
    #[wasm_bindgen(js_name = selectingTheNativeTierDoesNotMakeItNative)]
    pub fn selecting_the_native_tier_does_not_make_it_native(&self) -> bool {
        self.value.selecting_the_native_tier_does_not_make_it_native
    }
    /// 四个词各有精确谓词 / Whether the four tiers have exact predicates.
    #[wasm_bindgen(js_name = theFourTiersHaveExactPredicates)]
    pub fn the_four_tiers_have_exact_predicates(&self) -> bool {
        self.value.the_four_tiers_have_exact_predicates
    }
    /// `as_str` 是四个稳定名 / Whether `as_str` gives four stable names.
    #[wasm_bindgen(js_name = theStableNamesAreFourWords)]
    pub fn the_stable_names_are_four_words(&self) -> bool {
        self.value.the_stable_names_are_four_words
    }
}

/// 证据回映结论的独立 reader（续挖：`analysis/activation.rs` 的 `remap_backend_evidence`）。
/// Independent reader for the evidence-remap verdict (continuation).
#[wasm_bindgen]
pub struct EvidenceRemapReport { value: ospf_rust_bridge::EvidenceRemapReport }

#[wasm_bindgen]
impl EvidenceRemapReport {
    /// 解析并校验结果文本 / Parse and validate result text.
    #[wasm_bindgen(js_name = fromJson)]
    pub fn from_json(json: &str) -> Result<EvidenceRemapReport, JsValue> {
        if json.len() > 128 * 1024 { return Err(error("evidence remap report exceeds 128 KiB")); }
        let value: ospf_rust_bridge::EvidenceRemapReport = serde_json::from_str(json).map_err(error)?;
        // 读侧复核：来源种类在六词表里；`remapped` 里的每个身份都必须出现在来源列表里且标着 `remapped`；
        // 反过来标着 `remapped` 的来源也必须在 `remapped` 里；`objectiveTarget` 来源必须没有成员；
        // `sparseDomain` 来源的成员必须是 `domain:变量名`；`remapped` 允许重复（共享身份不合并）。
        // Read-side re-checks: the source kinds come from a six-word vocabulary; every identity in `remapped` appears in
        // the source list and is marked `remapped`; conversely a source marked `remapped` appears in `remapped`;
        // `objectiveTarget` sources carry no member; a `sparseDomain` member must be `domain:name`; and `remapped` may
        // legitimately repeat because shared identities are not deduped.
        let known_source_kinds = ["constraint", "variable-lower-bound", "variable-upper-bound",
            "variable-bound", "sparse-domain", "objective-target"];
        for source in &value.sources {
            if !known_source_kinds.contains(&source.kind.as_str()) {
                return Err(error("evidence remap report has an unknown source kind"));
            }
            if source.stable_id.trim().is_empty() {
                return Err(error("evidence remap report has a blank source identity"));
            }
            if source.kind == "objective-target" && source.member.is_some() {
                return Err(error("evidence remap report gives the objective target a member"));
            }
            if source.kind != "objective-target" && source.member.is_none() {
                return Err(error("evidence remap report drops a member from a mappable source"));
            }
            if let Some(member) = &source.member {
                let known = ["constraint:", "lowerBound:", "upperBound:", "domain:",
                    "interval:", "assumption:"];
                if !known.iter().any(|prefix| member.starts_with(prefix)) {
                    return Err(error("evidence remap report renders a member out of vocabulary"));
                }
            }
            if source.kind == "sparse-domain" {
                // 稀疏域内容不进成员：只允许 `domain:变量名`。 
                // The sparse-domain content never enters the member: only `domain:name` is allowed.
                let member = source.member.as_deref().unwrap_or_default();
                let name = source.stable_id.strip_prefix("variable:")
                    .and_then(|rest| rest.strip_suffix(":domain")).unwrap_or_default();
                if member != format!("domain:{name}") {
                    return Err(error("evidence remap report keeps the sparse-domain content"));
                }
            }
        }
        let remapped_present = value.sources.iter()
            .filter(|source| source.remapped)
            .map(|source| source.stable_id.clone())
            .collect::<std::collections::BTreeSet<_>>();
        let remapped_claimed = value.remapped.iter().cloned()
            .collect::<std::collections::BTreeSet<_>>();
        if remapped_present != remapped_claimed {
            return Err(error("evidence remap report disagrees between sources and remapped"));
        }
        if value.assumptions.iter().any(|id| id.trim().is_empty()) {
            return Err(error("evidence remap report has a blank assumption identity"));
        }
        if !value.objective_targets_have_no_evidence_member
            || !value.the_interval_member_can_never_match
            || !value.as_member_drops_the_sparse_domain_content
            || !value.direct_members_match_without_the_assumption_path
            || !value.the_assumption_path_reaches_bound_variants
            || !value.unknown_members_are_dropped
            || !value.deactivated_sources_are_never_remapped
            || !value.shared_identity_records_are_not_deduped
        {
            return Err(error("evidence remap report admits a broken remap rule"));
        }
        Ok(EvidenceRemapReport { value })
    }

    /// 原样文本 / Verbatim text.
    #[wasm_bindgen(js_name = toJson)]
    pub fn to_json(&self) -> Result<String, JsValue> {
        serde_json::to_string(&self.value).map_err(error)
    }
    /// 来源条数 / The source count.
    #[wasm_bindgen(js_name = sourceCount)]
    pub fn source_count(&self) -> u32 {
        u32::try_from(self.value.sources.len()).unwrap_or(u32::MAX)
    }
    /// 第 `index` 个来源的种类 / The source kind at `index`.
    #[wasm_bindgen(js_name = sourceKindAt)]
    pub fn source_kind_at(&self, index: u32) -> Result<String, JsValue> {
        self.source_at(index).map(|source| source.kind.clone())
    }
    /// 第 `index` 个来源的稳定身份 / The source identity at `index`.
    #[wasm_bindgen(js_name = sourceStableIdAt)]
    pub fn source_stable_id_at(&self, index: u32) -> Result<String, JsValue> {
        self.source_at(index).map(|source| source.stable_id.clone())
    }
    /// 第 `index` 个来源的证据成员（`undefined` 表示这一型没有成员）。
    /// The evidence member at `index`; `undefined` means this kind has no member.
    #[wasm_bindgen(js_name = sourceMemberAt)]
    pub fn source_member_at(&self, index: u32) -> Result<Option<String>, JsValue> {
        self.source_at(index).map(|source| source.member.clone())
    }
    /// 第 `index` 个来源是否被回映 / Whether the source at `index` is remapped.
    #[wasm_bindgen(js_name = sourceRemappedAt)]
    pub fn source_remapped_at(&self, index: u32) -> Result<bool, JsValue> {
        self.source_at(index).map(|source| source.remapped)
    }
    /// 回映条数（**可能多于来源数**，因为共享身份不合并）。 / The remap count (it may exceed the source count).
    #[wasm_bindgen(js_name = remappedCount)]
    pub fn remapped_count(&self) -> u32 {
        u32::try_from(self.value.remapped.len()).unwrap_or(u32::MAX)
    }
    /// 第 `index` 个回映身份 / The remapped identity at `index`.
    #[wasm_bindgen(js_name = remappedAt)]
    pub fn remapped_at(&self, index: u32) -> Result<String, JsValue> {
        self.value.remapped
            .get(usize::try_from(index).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("remapped index out of range"))
    }
    /// assumption 条数 / The assumption count.
    #[wasm_bindgen(js_name = assumptionCount)]
    pub fn assumption_count(&self) -> u32 {
        u32::try_from(self.value.assumptions.len()).unwrap_or(u32::MAX)
    }
    /// 第 `index` 个 assumption 身份 / The assumption identity at `index`.
    #[wasm_bindgen(js_name = assumptionAt)]
    pub fn assumption_at(&self, index: u32) -> Result<String, JsValue> {
        self.value.assumptions
            .get(usize::try_from(index).map_err(|_| error("index overflow"))?)
            .cloned().ok_or_else(|| error("assumption index out of range"))
    }
    /// `objectiveTarget` 没有证据成员 / Whether the objective target has no evidence member.
    #[wasm_bindgen(js_name = objectiveTargetsHaveNoEvidenceMember)]
    pub fn objective_targets_have_no_evidence_member(&self) -> bool {
        self.value.objective_targets_have_no_evidence_member
    }
    /// `Interval` 成员永远匹配不上 / Whether the `Interval` member can never match.
    #[wasm_bindgen(js_name = theIntervalMemberCanNeverMatch)]
    pub fn the_interval_member_can_never_match(&self) -> bool {
        self.value.the_interval_member_can_never_match
    }
    /// 成员丢掉稀疏域内容 / Whether the member drops the sparse-domain content.
    #[wasm_bindgen(js_name = asMemberDropsTheSparseDomainContent)]
    pub fn as_member_drops_the_sparse_domain_content(&self) -> bool {
        self.value.as_member_drops_the_sparse_domain_content
    }
    /// 直接成员无需 assumption 路径 / Whether direct members need no assumption path.
    #[wasm_bindgen(js_name = directMembersMatchWithoutTheAssumptionPath)]
    pub fn direct_members_match_without_the_assumption_path(&self) -> bool {
        self.value.direct_members_match_without_the_assumption_path
    }
    /// assumption 路径靠共享身份命中边界变体 / Whether the assumption path reaches bound variants.
    #[wasm_bindgen(js_name = theAssumptionPathReachesBoundVariants)]
    pub fn the_assumption_path_reaches_bound_variants(&self) -> bool {
        self.value.the_assumption_path_reaches_bound_variants
    }
    /// 未知成员被丢弃 / Whether unknown members are dropped.
    #[wasm_bindgen(js_name = unknownMembersAreDropped)]
    pub fn unknown_members_are_dropped(&self) -> bool { self.value.unknown_members_are_dropped }
    /// 停用记录不参与回映 / Whether deactivated records never take part.
    #[wasm_bindgen(js_name = deactivatedSourcesAreNeverRemapped)]
    pub fn deactivated_sources_are_never_remapped(&self) -> bool {
        self.value.deactivated_sources_are_never_remapped
    }
    /// 共享身份的两条记录不合并 / Whether shared-identity records stay separate.
    #[wasm_bindgen(js_name = sharedIdentityRecordsAreNotDeduped)]
    pub fn shared_identity_records_are_not_deduped(&self) -> bool {
        self.value.shared_identity_records_are_not_deduped
    }

    /// 取一个来源（内部）。 / Fetch one source (internal).
    fn source_at(&self, index: u32) -> Result<&ospf_rust_bridge::EvidenceSourceView, JsValue> {
        self.value.sources
            .get(usize::try_from(index).map_err(|_| error("index overflow"))?)
            .ok_or_else(|| error("source index out of range"))
    }
}

