    pub fn report_valid(&self) -> bool { self.value.report_valid }
    /// 校验错误文本 / The validation error text.
    #[wasm_bindgen(js_name = reportError)]
    pub fn report_error(&self) -> String { self.value.report_error.clone() }
    /// 是否有 incumbent / Whether an incumbent exists.
    #[wasm_bindgen(js_name = hasIncumbent)]
    pub fn has_incumbent(&self) -> bool { self.value.has_incumbent }
    /// 是否最优 / Whether the presence is optimal.
    #[wasm_bindgen(js_name = isOptimal)]
    pub fn is_optimal(&self) -> bool { self.value.is_optimal }
    /// 是否给出 payload / Whether a payload is available.
    #[wasm_bindgen(js_name = incumbentPresent)]
    pub fn incumbent_present(&self) -> bool { self.value.incumbent_present }
    /// 谓词只看 presence / Whether the incumbent predicate reads only the presence.
    #[wasm_bindgen(js_name = hasIncumbentReadsOnlyThePresence)]
    pub fn has_incumbent_reads_only_the_presence(&self) -> bool {
        self.value.has_incumbent_reads_only_the_presence
    }
    /// 最优谓词只看 presence / Whether the optimal predicate reads only the presence.
    #[wasm_bindgen(js_name = isOptimalReadsOnlyThePresence)]
    pub fn is_optimal_reads_only_the_presence(&self) -> bool {
        self.value.is_optimal_reads_only_the_presence
    }
    /// 谓词从不校验报告 / Whether the predicates never validate.
    #[wasm_bindgen(js_name = thePredicatesNeverValidateTheReport)]
    pub fn the_predicates_never_validate_the_report(&self) -> bool {
        self.value.the_predicates_never_validate_the_report
    }
