    #[wasm_bindgen(js_name = theIncumbentReadsTheTypedValue)]
    pub fn the_incumbent_reads_the_typed_value(&self) -> bool {
        self.value.the_incumbent_reads_the_typed_value
    }
    /// 诊断面从不被校验 / Whether the diagnostics are never validated.
    #[wasm_bindgen(js_name = theDiagnosticsAreNeverValidated)]
    pub fn the_diagnostics_are_never_validated(&self) -> bool {
        self.value.the_diagnostics_are_never_validated
    }
    /// satisfied 与 violation 不互校 / Whether the two are never cross-checked.
    #[wasm_bindgen(js_name = satisfiedAndViolationAreNeverCrossChecked)]
    pub fn satisfied_and_violation_are_never_cross_checked(&self) -> bool {
        self.value.satisfied_and_violation_are_never_cross_checked
    }
