    pub fn report_valid(&self) -> bool { self.value.report_valid }
    /// 报告校验的错误文本 / The report error text.
    #[wasm_bindgen(js_name = reportError)]
    pub fn report_error(&self) -> String { self.value.report_error.clone() }
    /// 是否有对偶 / Whether at least one dual is present.
    #[wasm_bindgen(js_name = hasDuals)]
    pub fn has_duals(&self) -> bool { self.value.has_duals }
    /// 查询命中的对偶值 / The dual of the queried record.
    #[wasm_bindgen(js_name = queryDual)]
