    /// 是否非空 / Whether the descriptor is not empty.
    #[wasm_bindgen(js_name = notEmpty)]
    pub fn not_empty(&self) -> bool { self.value.not_empty }
    /// `Auto` 的判定 / The `Auto` verdict.
    #[wasm_bindgen(js_name = autoSupported)]
    pub fn auto_supported(&self) -> bool { self.value.auto_supported }
    /// `Always` 的判定 / The `Always` verdict.
    #[wasm_bindgen(js_name = alwaysSupported)]
    pub fn always_supported(&self) -> bool { self.value.always_supported }
    /// `Never` 的判定 / The `Never` verdict.
    #[wasm_bindgen(js_name = neverSupported)]
    pub fn never_supported(&self) -> bool { self.value.never_supported }
    /// `OnlyAsc` 的判定 / The `OnlyAsc` verdict.
    #[wasm_bindgen(js_name = onlyAscSupported)]
    pub fn only_asc_supported(&self) -> bool { self.value.only_asc_supported }
    /// then 家族追加到末尾 / Whether the `then` family appends to the tail.
    #[wasm_bindgen(js_name = theThenFamilyAppendsToTheTail)]
    pub fn the_then_family_appends_to_the_tail(&self) -> bool {
        self.value.the_then_family_appends_to_the_tail
    }
    /// 同路径不合并 / Whether the same path stays unmerged.
    #[wasm_bindgen(js_name = thenDoesNotMergeTheSamePath)]
    pub fn then_does_not_merge_the_same_path(&self) -> bool {
        self.value.then_does_not_merge_the_same_path
    }
    /// Add 就是 then / Whether `Add` is `then`.
    #[wasm_bindgen(js_name = theAddOperatorIsThen)]
    pub fn the_add_operator_is_then(&self) -> bool { self.value.the_add_operator_is_then }
    /// 空非空互补 / Whether emptiness is complementary.
    #[wasm_bindgen(js_name = emptinessIsComplementary)]
    pub fn emptiness_is_complementary(&self) -> bool { self.value.emptiness_is_complementary }
    /// 支持判据只看方向 / Whether the support test reads the direction only.
