    /// 读取错误文本 / The read error text.
    #[wasm_bindgen(js_name = toError)]
    pub fn to_error(&self) -> String { self.value.to_error.clone() }
    /// 两种策略是否一致 / Whether both policies agree.
    #[wasm_bindgen(js_name = policiesAgree)]
    pub fn policies_agree(&self) -> bool { self.value.policies_agree }
    /// 上界是否成功 / Whether the bound succeeded.
    #[wasm_bindgen(js_name = upperBoundOk)]
    pub fn upper_bound_ok(&self) -> bool { self.value.upper_bound_ok }
    /// 上界的值 / The bound itself.
    #[wasm_bindgen(js_name = upperBound)]
