    #[wasm_bindgen(js_name = rowErrors)]
    pub fn row_errors(&self) -> Vec<String> {
        self.value.rows.iter().map(|row| row.error.clone()).collect()
    }
    /// 每次注册的面 / The face per row.
    #[wasm_bindgen(js_name = rowFaces)]
    pub fn row_faces(&self) -> Vec<String> {
        self.value.rows.iter().map(|row| row.face.clone()).collect()
    }
    /// 每次注册的 id / The operator id per row.
    #[wasm_bindgen(js_name = rowIds)]
    pub fn row_ids(&self) -> Vec<String> {
        self.value.rows.iter().map(|row| row.id.clone()).collect()
    }
    /// 各面累计被接受数 / The accepted tally per row.
    #[wasm_bindgen(js_name = rowAcceptedOnFace)]
    pub fn row_accepted_on_face(&self) -> Vec<f64> {
        self.value.rows.iter().map(|row| f64::from(row.accepted_on_face)).collect()
    }
    /// 累计被接受总数 / The total accepted tally per row.
    #[wasm_bindgen(js_name = rowTotalAccepted)]
    pub fn row_total_accepted(&self) -> Vec<f64> {
        self.value.rows.iter().map(|row| f64::from(row.total_accepted)).collect()
    }
    /// 空编码表被拒 / Whether an empty encoding list is refused.
    #[wasm_bindgen(js_name = anEmptyEncodingListIsRefused)]
    pub fn an_empty_encoding_list_is_refused(&self) -> bool {
        self.value.an_empty_encoding_list_is_refused
    }
    /// 非相邻重复被拒 / Whether a non-adjacent repeat is refused.
    #[wasm_bindgen(js_name = aNonAdjacentRepeatIsRefused)]
    pub fn a_non_adjacent_repeat_is_refused(&self) -> bool {
        self.value.a_non_adjacent_repeat_is_refused
    }
    /// 合法声明真的注册上 / Whether a legal declaration registers.
    #[wasm_bindgen(js_name = aLegalDeclarationRegisters)]
